// BWL – Rechnungswesen, Controlling, Finanzierung, Investition, Steuern, Produktion & Logistik
(window.SLIDES = window.SLIDES || []).push(
  // ── Bilanz ──
  { id: "bw2-001", cat: "bwl", topic: "Bilanz", type: "fact", emoji: "⚖️", level: 1,
    title: "Bilanzgleichung: Aktiva = Passiva",
    text: "Die Bilanz zeigt zum Stichtag zwei Sichten auf dasselbe Geld: **Aktiva** = wofür es steckt (Vermögen), **Passiva** = woher es kommt (Eigen- + Fremdkapital). Deshalb sind beide Seiten immer exakt gleich groß.",
    more: "Merkhilfe: Passiva = Herkunft („Wer hat bezahlt?“), Aktiva = Verwendung („Was wurde gekauft?“). Jede Buchung verändert die Bilanz so, dass die Gleichung hält – entweder auf einer Seite (Tausch) oder auf beiden (Verlängerung/Verkürzung)." },
  { id: "bw2-002", cat: "bwl", topic: "Bilanz", type: "flashcard", emoji: "🏗️", level: 1,
    term: "Anlagevermögen vs. Umlaufvermögen",
    def: "Anlagevermögen dient dem Betrieb dauerhaft (Gebäude, Maschinen, Patente, Beteiligungen). Umlaufvermögen ist zum Verbrauch, Verkauf oder kurzfristigen Umschlag bestimmt (Vorräte, Forderungen, Bank).",
    example: "Der Lieferwagen eines Bäckers ist Anlagevermögen – derselbe Wagen beim Autohändler ist Umlaufvermögen (Ware)." },
  { id: "bw2-003", cat: "bwl", topic: "Bilanz", type: "quiz", emoji: "🏢", level: 1,
    q: "Welche Position gehört zum Anlagevermögen?",
    options: ["Vorräte an Rohstoffen", "Forderungen aus Lieferungen und Leistungen", "Selbst genutztes Betriebsgebäude", "Kassenbestand"],
    answer: 2,
    explain: "Das Betriebsgebäude dient dem Unternehmen dauerhaft → Anlagevermögen. Vorräte, Forderungen und Kasse sind Umlaufvermögen." },
  { id: "bw2-004", cat: "bwl", topic: "Bilanz", type: "whatif", emoji: "🏭", level: 1,
    q: "Was passiert, wenn ein Unternehmen eine Maschine auf Kredit kauft?",
    steps: ["Aktiva: Sachanlagen steigen", "Passiva: Verbindlichkeiten steigen", "Bilanzsumme wächst auf beiden Seiten", "EK bleibt gleich → EK-Quote sinkt"],
    text: "Das ist eine **Bilanzverlängerung** (Aktiv-Passiv-Mehrung). Der Gewinn ändert sich beim Kauf nicht – erst die Abschreibungen und Zinsen der Folgejahre wirken in der GuV." },
  { id: "bw2-005", cat: "bwl", topic: "Bilanz", type: "quiz", emoji: "🔄", level: 2,
    q: "Ein Kunde begleicht eine offene Rechnung per Überweisung. Welcher Bilanzvorgang ist das?",
    options: ["Aktivtausch", "Passivtausch", "Bilanzverlängerung", "Bilanzverkürzung"],
    answer: 0,
    explain: "Forderungen sinken, Bankguthaben steigt – beides Aktiva. Die Bilanzsumme bleibt gleich: **Aktivtausch**." },
  { id: "bw2-006", cat: "bwl", topic: "Bilanz", type: "truefalse", emoji: "🏦", level: 2,
    q: "Tilgt ein Unternehmen ein Darlehen vom Bankkonto, bleibt die Bilanzsumme gleich.",
    answer: false,
    explain: "Bank (Aktiva) und Verbindlichkeiten (Passiva) sinken gleichzeitig → **Bilanzverkürzung** (Aktiv-Passiv-Minderung). Die Bilanzsumme schrumpft um den Tilgungsbetrag." },
  { id: "bw2-007", cat: "bwl", topic: "Bilanz", type: "order", emoji: "📋", level: 2,
    q: "Sortiere die Aktivseite nach § 266 HGB (von oben nach unten).",
    items: ["Immaterielle Vermögensgegenstände", "Sachanlagen", "Finanzanlagen", "Vorräte", "Kassenbestand, Bankguthaben"],
    explain: "Die Aktivseite ist nach **steigender Liquidität** gegliedert: erst Anlagevermögen (immateriell → Sach → Finanz), dann Umlaufvermögen (Vorräte → Forderungen → Wertpapiere → flüssige Mittel)." },
  { id: "bw2-008", cat: "bwl", topic: "Bilanz", type: "flashcard", emoji: "🔁", level: 2,
    term: "Passivtausch",
    def: "Umschichtung nur auf der Passivseite – die Bilanzsumme bleibt gleich. Typisch: Umwandlung von Fremd- in Eigenkapital oder von kurz- in langfristige Schulden.",
    example: "Eine Lieferantenverbindlichkeit wird durch ein Bankdarlehen abgelöst: Verbindlichkeiten aLuL ↓, Darlehen ↑." },
  { id: "bw2-009", cat: "bwl", topic: "Bilanz", type: "quiz", emoji: "🧮", level: 2,
    q: "Bilanzsumme 2,0 Mio €, Eigenkapital 0,5 Mio €. Es werden Waren für 100.000 € auf Ziel gekauft. Wie lauten Bilanzsumme und EK-Quote danach?",
    options: ["2,0 Mio € / 25,0 %", "2,1 Mio € / 25,0 %", "1,9 Mio € / 26,3 %", "2,1 Mio € / 23,8 %"],
    answer: 3,
    explain: "Kauf auf Ziel = Bilanzverlängerung: 2,1 Mio €. EK bleibt 0,5 Mio € → 0,5 / 2,1 = **23,8 %**. Mehr Schulden drücken die Quote, auch ohne Verlust." },
  { id: "bw2-010", cat: "bwl", topic: "Bilanz", type: "fact", emoji: "🧩", level: 2,
    title: "Eigenkapital ist eine Restgröße",
    text: "EK wird nicht „gezählt“, sondern ergibt sich: **Vermögen − Schulden = Eigenkapital**. Sinkt der Wert des Vermögens (Abschreibung, Verlust), sinkt automatisch das EK.",
    more: "Ist das EK aufgezehrt, steht in der HGB-Bilanz auf der Aktivseite ein „nicht durch Eigenkapital gedeckter Fehlbetrag“. Das ist ein Warnsignal – aber noch nicht automatisch Überschuldung im insolvenzrechtlichen Sinn (dort zählt u. a. die Fortführungsprognose)." },
  { id: "bw2-011", cat: "bwl", topic: "Bilanz", type: "truefalse", emoji: "💶", level: 1,
    q: "Das Eigenkapital ist das Geld, das auf dem Bankkonto des Unternehmens liegt.",
    answer: false,
    explain: "EK steht auf der Passivseite und sagt nur, wie viel Vermögen den Eigentümern „gehört“. Wo das Geld steckt (Maschinen, Vorräte, Bank), zeigt die Aktivseite. Hohes EK und leeres Konto schließen sich nicht aus." },
  { id: "bw2-012", cat: "bwl", topic: "Bilanz", type: "whatif", emoji: "🩸", level: 2,
    q: "Was passiert, wenn ein Unternehmen einen Jahresfehlbetrag (Verlust) macht?",
    steps: ["GuV: Aufwendungen > Erträge", "Eigenkapital sinkt um den Verlust", "Vermögen sinkt oder Schulden steigen", "EK-Quote fällt, Rating verschlechtert sich"],
    text: "Ein Verlust frisst sich direkt ins Eigenkapital – es ist der Puffer, der Verluste auffängt. Wiederholte Verluste können das EK aufzehren; dann drohen Covenant-Brüche und die Prüfung der insolvenzrechtlichen Überschuldung." },

  // ── GuV ──
  { id: "bw2-013", cat: "bwl", topic: "GuV", type: "fact", emoji: "📈", level: 1,
    title: "Bilanz = Foto, GuV = Film",
    text: "Die Bilanz zeigt **Bestände** an einem Stichtag. Die Gewinn- und Verlustrechnung zeigt **Ströme** über ein Jahr: Erträge − Aufwendungen = Jahresüberschuss bzw. -fehlbetrag.",
    more: "Verbindung: Der Jahresüberschuss der GuV erhöht das Eigenkapital in der Bilanz. Deshalb „schließt“ die GuV über das Eigenkapitalkonto ab – beide Rechenwerke passen immer zusammen." },
  { id: "bw2-014", cat: "bwl", topic: "GuV", type: "flashcard", emoji: "🏭", level: 2,
    term: "Gesamtkostenverfahren (GKV)",
    def: "Stellt allen Erträgen der Periode alle Aufwendungen nach Arten gegenüber (Material, Personal, Abschreibungen …). Produziert, aber nicht verkauft? → Ausgleich über „Bestandsveränderungen“.",
    example: "In Deutschland traditionell verbreitet (§ 275 Abs. 2 HGB); gut erkennbar: Wie viel kostet das Personal insgesamt?" },
  { id: "bw2-015", cat: "bwl", topic: "GuV", type: "flashcard", emoji: "🛒", level: 2,
    term: "Umsatzkostenverfahren (UKV)",
    def: "Stellt den Umsatzerlösen nur die Kosten der verkauften Produkte gegenüber, gegliedert nach Funktionen: Herstellung, Vertrieb, Verwaltung. Ergebnis: Bruttoergebnis vom Umsatz.",
    example: "International üblich (US-GAAP, viele IFRS-Konzerne); zeigt direkt die Bruttomarge." },
  { id: "bw2-016", cat: "bwl", topic: "GuV", type: "truefalse", emoji: "⚖️", level: 2,
    q: "Gesamtkosten- und Umsatzkostenverfahren führen zu unterschiedlichen Jahresüberschüssen.",
    answer: false,
    explain: "Beide Verfahren gliedern nur anders (nach Kostenarten vs. Funktionen). Bei gleicher Bewertung ergibt sich **derselbe Jahresüberschuss**." },
  { id: "bw2-017", cat: "bwl", topic: "GuV", type: "quiz", emoji: "🔍", level: 3,
    q: "Welche GuV-Position gibt es nur beim Gesamtkostenverfahren?",
    options: ["Vertriebskosten", "Bestandsveränderungen an fertigen und unfertigen Erzeugnissen", "Allgemeine Verwaltungskosten", "Herstellungskosten der zur Erzielung der Umsatzerlöse erbrachten Leistungen"],
    answer: 1,
    explain: "Das GKV erfasst alle Produktionsaufwendungen und korrigiert über **Bestandsveränderungen** (und aktivierte Eigenleistungen). Die anderen drei sind typische UKV-Funktionsposten." },
  { id: "bw2-018", cat: "bwl", topic: "GuV", type: "order", emoji: "🪜", level: 2,
    q: "Ordne die Ergebnisgrößen von oben nach unten in der GuV-Staffel.",
    items: ["Umsatz", "EBITDA", "EBIT", "EBT", "Jahresüberschuss"],
    explain: "Umsatz − operative Aufwendungen = **EBITDA**; − Abschreibungen = **EBIT**; ± Finanzergebnis (Zinsen) = **EBT**; − Ertragsteuern = **Jahresüberschuss**." },
  { id: "bw2-019", cat: "bwl", topic: "GuV", type: "quiz", emoji: "🧮", level: 1,
    q: "Erträge 1,2 Mio €, Aufwendungen 1,05 Mio €. Wie hoch ist der Jahresüberschuss?",
    options: ["1,05 Mio €", "250.000 €", "150.000 €", "2,25 Mio €"],
    answer: 2,
    explain: "1.200.000 − 1.050.000 = **150.000 €**. Dieser Betrag erhöht (sofern nicht ausgeschüttet) das Eigenkapital." },

  // ── Cashflow ──
  { id: "bw2-020", cat: "bwl", topic: "Cashflow", type: "fact", emoji: "💸", level: 1,
    title: "Gewinn ist eine Meinung, Cash ist ein Fakt",
    text: "Gewinn entsteht, wenn Umsatz gebucht wird – Cash erst, wenn der Kunde zahlt. Abschreibungen senken den Gewinn ohne Geldabfluss, Investitionen kosten Geld ohne sofortigen Aufwand. Unternehmen gehen an fehlender **Liquidität** pleite, nicht an fehlendem Gewinn.",
    more: "Typischer Fehler: Gewinn mit verfügbarem Geld gleichsetzen. Ein wachsender Mittelständler kann Rekordgewinne schreiben und trotzdem zahlungsunfähig werden, weil Vorräte und Forderungen das Geld binden." },
  { id: "bw2-021", cat: "bwl", topic: "Cashflow", type: "number", emoji: "🧭", level: 2,
    value: "3", label: "Bereiche der Kapitalflussrechnung",
    text: "Cashflow aus **laufender Geschäftstätigkeit**, aus **Investitionstätigkeit** und aus **Finanzierungstätigkeit**. Ihre Summe = Veränderung des Finanzmittelfonds.",
    more: "Lesemuster eines gesunden Unternehmens: operativ deutlich positiv, Investitionen negativ (es wird investiert), Finanzierung negativ (Tilgung, Dividenden). Ist der operative Cashflow dauerhaft negativ und wird über Kredite gestopft, ist Vorsicht geboten." },
  { id: "bw2-022", cat: "bwl", topic: "Cashflow", type: "order", emoji: "🪜", level: 3,
    q: "Ordne die Schritte der indirekten Cashflow-Ermittlung.",
    items: ["Jahresüberschuss", "+ Abschreibungen (nicht zahlungswirksam)", "− Zunahme des Working Capital", "= Operativer Cashflow", "− Investitionen = Free Cashflow"],
    explain: "Die indirekte Methode startet beim Gewinn und korrigiert alles, was nicht zahlungswirksam war. Danach zieht man die Investitionsauszahlungen ab." },
  { id: "bw2-023", cat: "bwl", topic: "Cashflow", type: "quiz", emoji: "🧮", level: 2,
    q: "Jahresüberschuss 200.000 €, Abschreibungen 80.000 €, Forderungen steigen um 50.000 €. Operativer Cashflow (indirekt)?",
    options: ["330.000 €", "230.000 €", "170.000 €", "280.000 €"],
    answer: 1,
    explain: "200.000 + 80.000 (Abschreibung addieren) − 50.000 (Forderungszuwachs = Geld noch nicht da) = **230.000 €**." },
  { id: "bw2-024", cat: "bwl", topic: "Cashflow", type: "whatif", emoji: "⏳", level: 1,
    q: "Was passiert, wenn Kunden später zahlen?",
    steps: ["Forderungen steigen, DSO steigt", "Umsatz und Gewinn bleiben gleich", "Operativer Cashflow sinkt", "Finanzierungsbedarf steigt (Kontokorrent)"],
    text: "Längere Zahlungsziele sind ein **zinsloser Kredit an den Kunden**. Der Gewinn ist schon gebucht, das Geld fehlt aber – im Extremfall droht trotz Gewinn ein Liquiditätsengpass." },
  { id: "bw2-025", cat: "bwl", topic: "Cashflow", type: "truefalse", emoji: "📉", level: 2,
    q: "Abschreibungen senken den Gewinn, aber nicht den Cashflow der Periode.",
    answer: true,
    explain: "Das Geld floss beim Kauf der Anlage ab (Investitions-Cashflow). Die Abschreibung verteilt nur den Aufwand – deshalb wird sie bei der indirekten Methode wieder **addiert**. (Indirekt hilft sie sogar: Sie senkt die Steuerzahlung.)" },
  { id: "bw2-026", cat: "bwl", topic: "Cashflow", type: "flashcard", emoji: "🆓", level: 2,
    term: "Free Cashflow (FCF)",
    def: "Operativer Cashflow minus Investitionen (Capex). Das Geld, das nach Erhalt und Ausbau des Geschäfts übrig bleibt – für Tilgung, Dividenden, Rückkäufe oder Zukäufe.",
    example: "Operativer CF 5 Mio €, Capex 3 Mio € → FCF 2 Mio €. Basis jeder DCF-Bewertung." },
  { id: "bw2-027", cat: "bwl", topic: "Cashflow", type: "quiz", emoji: "💰", level: 3,
    q: "Wo erscheint eine gezahlte Dividende in der HGB-Kapitalflussrechnung (DRS 21)?",
    options: ["Laufende Geschäftstätigkeit", "Investitionstätigkeit", "Gar nicht, sie ist kein Zahlungsstrom", "Finanzierungstätigkeit"],
    answer: 3,
    explain: "Dividenden sind Zahlungen an Eigenkapitalgeber → **Finanzierungstätigkeit** (wie Kreditaufnahme und Tilgung). Nach IFRS besteht hier ein Ausweiswahlrecht." },
  { id: "bw2-028", cat: "bwl", topic: "Cashflow", type: "whatif", emoji: "🚀", level: 2,
    q: "Was passiert, wenn ein profitables Unternehmen sehr schnell wächst?",
    steps: ["Mehr Aufträge → mehr Vorräte nötig", "Mehr Umsatz → mehr offene Forderungen", "Working Capital bindet Cash", "Liquiditätslücke trotz Gewinn"],
    text: "**Overtrading**: Wachstum muss vorfinanziert werden. Deshalb planen Gründer und CFOs Liquidität separat vom Gewinn – und sichern Kreditlinien, bevor sie gebraucht werden." },

  // ── Buchführung ──
  { id: "bw2-029", cat: "bwl", topic: "Buchführung", type: "fact", emoji: "📒", level: 1,
    title: "Doppelte Buchführung: jede Buchung zweimal",
    text: "Jeder Geschäftsvorfall wird auf mindestens zwei Konten gebucht – einmal im **Soll** (links), einmal im **Haben** (rechts), betragsgleich. 1494 von Luca Pacioli in Venedig beschrieben.",
    more: "Der Clou: Weil Soll immer = Haben ist, sind Rechenfehler auffindbar, und der Gewinn wird doppelt ermittelt – über die GuV und über den Eigenkapitalvergleich in der Bilanz. Beide Wege müssen dasselbe Ergebnis liefern." },
  { id: "bw2-030", cat: "bwl", topic: "Buchführung", type: "flashcard", emoji: "✍️", level: 1,
    term: "Buchungssatz",
    def: "Formel „**Soll an Haben**“: zuerst das Konto mit der Soll-Buchung, dann „an“, dann das Konto mit der Haben-Buchung, jeweils mit Betrag.",
    example: "Barkauf von Büromaterial für 50 €: Bürobedarf 50 an Kasse 50." },
  { id: "bw2-031", cat: "bwl", topic: "Buchführung", type: "quiz", emoji: "🧾", level: 2,
    q: "Ein Kunde zahlt 5.000 € Rechnung per Bank. Wie lautet der Buchungssatz?",
    options: ["Forderungen an Bank 5.000", "Umsatzerlöse an Bank 5.000", "Bank an Forderungen 5.000", "Bank an Umsatzerlöse 5.000"],
    answer: 2,
    explain: "Bank (Aktivkonto) nimmt zu → Soll. Forderungen (Aktivkonto) nehmen ab → Haben. Der Umsatz wurde schon bei Rechnungsstellung gebucht – nicht nochmal!" },
  { id: "bw2-032", cat: "bwl", topic: "Buchführung", type: "truefalse", emoji: "↔️", level: 2,
    q: "Auf Aktivkonten werden Zugänge im Haben gebucht.",
    answer: false,
    explain: "Aktivkonten: Anfangsbestand und Zugänge im **Soll**, Abgänge im Haben. Passivkonten genau umgekehrt. Merkhilfe: Das Konto „wächst“ auf der Seite, auf der es in der Bilanz steht." },
  { id: "bw2-033", cat: "bwl", topic: "Buchführung", type: "quiz", emoji: "📦", level: 2,
    q: "Wareneinkauf auf Ziel: 1.000 € netto + 19 % USt. Welche Buchung ist richtig?",
    options: ["Waren 1.000, Vorsteuer 190 an Verbindlichkeiten aLuL 1.190", "Waren 1.190 an Verbindlichkeiten aLuL 1.190", "Verbindlichkeiten aLuL 1.190 an Waren 1.000, Vorsteuer 190", "Waren 1.000, Umsatzsteuer 190 an Bank 1.190"],
    answer: 0,
    explain: "Die gezahlte USt ist **Vorsteuer** (Forderung ans Finanzamt) und wird separat gebucht. „Auf Ziel“ = Verbindlichkeit, nicht Bank." },
  { id: "bw2-034", cat: "bwl", topic: "Buchführung", type: "flashcard", emoji: "🔚", level: 2,
    term: "Erfolgskonten",
    def: "Aufwands- und Ertragskonten sind Unterkonten des Eigenkapitals. Aufwand steht im Soll (mindert EK), Ertrag im Haben (mehrt EK). Abschluss über das GuV-Konto, dessen Saldo ins Eigenkapital geht.",
    example: "Miete 2.000 € per Bank: Mietaufwand an Bank – das EK sinkt indirekt um 2.000 €." },
  { id: "bw2-035", cat: "bwl", topic: "Buchführung", type: "order", emoji: "📦", level: 1,
    q: "Bringe die Schritte des Jahresabschlusses in die richtige Reihenfolge.",
    items: ["Inventur (körperliche Bestandsaufnahme)", "Inventar (ausführliches Bestandsverzeichnis)", "Bilanz (kurze Gegenüberstellung in Kontenform)"],
    explain: "Erst zählen und messen (**Inventur**), dann alles mengen- und wertmäßig auflisten (**Inventar**), dann zur **Bilanz** verdichten." },
  { id: "bw2-036", cat: "bwl", topic: "Buchführung", type: "fact", emoji: "🗄️", level: 2,
    title: "Keine Buchung ohne Beleg",
    text: "Das **Belegprinzip** gehört zu den Grundsätzen ordnungsmäßiger Buchführung (GoB). Aufbewahrung (Stand 2025): Bücher und Jahresabschlüsse 10 Jahre, Buchungsbelege seit 2025 nur noch 8 Jahre.",
    more: "Die Verkürzung von 10 auf 8 Jahre für Buchungsbelege kam mit dem Bürokratieentlastungsgesetz IV. Praxis: Rechnungen dürfen digital archiviert werden, wenn sie unveränderbar und lesbar bleiben (GoBD)." },

  // ── Abschreibungen ──
  { id: "bw2-037", cat: "bwl", topic: "Abschreibungen", type: "fact", emoji: "📉", level: 1,
    title: "Abschreibung verteilt Kosten über die Nutzungsdauer",
    text: "Eine Maschine für 50.000 €, die 5 Jahre hält, wird nicht im Kaufjahr voll als Aufwand gebucht, sondern **linear** mit 10.000 € pro Jahr. So trägt jedes Nutzungsjahr seinen Anteil.",
    more: "Steuerlich heißt sie **AfA** (Absetzung für Abnutzung). Die Nutzungsdauern geben die amtlichen AfA-Tabellen vor. Im Anschaffungsjahr wird monatsgenau (pro rata temporis) abgeschrieben: Kauf im Oktober → 3/12 der Jahres-AfA." },
  { id: "bw2-038", cat: "bwl", topic: "Abschreibungen", type: "quiz", emoji: "🧮", level: 1,
    q: "Ein Firmenwagen kostet 36.000 € netto, Nutzungsdauer 6 Jahre. Lineare Jahresabschreibung?",
    options: ["3.600 €", "7.200 €", "4.500 €", "6.000 €"],
    answer: 3,
    explain: "36.000 € / 6 Jahre = **6.000 € pro Jahr**." },
  { id: "bw2-039", cat: "bwl", topic: "Abschreibungen", type: "quiz", emoji: "📊", level: 2,
    q: "Maschine: Anschaffung 80.000 € am 1. Januar, Nutzungsdauer 8 Jahre, linear. Restbuchwert nach 3 Jahren?",
    options: ["50.000 €", "30.000 €", "60.000 €", "40.000 €"],
    answer: 0,
    explain: "Jährliche AfA 10.000 €; nach 3 Jahren 30.000 € abgeschrieben → Restbuchwert **50.000 €**." },
  { id: "bw2-040", cat: "bwl", topic: "Abschreibungen", type: "number", emoji: "🖊️", level: 2,
    value: "800 €", label: "GWG-Grenze für Sofortabschreibung (netto, Stand 2025)",
    text: "Geringwertige Wirtschaftsgüter bis 800 € netto dürfen im Anschaffungsjahr **voll abgeschrieben** werden, wenn sie selbstständig nutzbar sind.",
    more: "Typischer Fehler: Bruttopreis ansetzen. Beim vorsteuerabzugsberechtigten Unternehmen zählt der Nettobetrag – ein Bürostuhl für 900 € brutto (756 € netto) ist GWG. Alternativ gibt es den Sammelposten (Poolabschreibung). Nicht selbstständig nutzbar ist z. B. ein Druckerkabel." },
  { id: "bw2-041", cat: "bwl", topic: "Abschreibungen", type: "truefalse", emoji: "💻", level: 2,
    q: "Ein Laptop für 1.200 € netto muss steuerlich zwingend über 3 Jahre abgeschrieben werden.",
    answer: false,
    explain: "Seit 2021 darf für Computerhardware und Software laut BMF-Schreiben eine **Nutzungsdauer von 1 Jahr** angesetzt werden – faktisch Sofortabschreibung, unabhängig von der GWG-Grenze (Stand 2025)." },
  { id: "bw2-042", cat: "bwl", topic: "Abschreibungen", type: "flashcard", emoji: "📐", level: 3,
    term: "Degressive Abschreibung",
    def: "Fester Prozentsatz vom Restbuchwert → anfangs hohe, später kleinere Abschreibung. Steuerlich nur zeitweise erlaubt; Stand 2025: für Anschaffungen Juli 2025 bis Ende 2027 bis zum 3-Fachen der linearen Rate, max. 30 %.",
    example: "100.000 €, 30 %: Jahr 1 → 30.000 €, Jahr 2 → 21.000 €, Jahr 3 → 14.700 €. Effekt: Steuern werden in die Zukunft verschoben (Liquiditätsvorteil)." },
  { id: "bw2-043", cat: "bwl", topic: "Abschreibungen", type: "quiz", emoji: "🎯", level: 2,
    q: "Welche Wirkung hat eine höhere Abschreibung im laufenden Jahr (bei sonst gleichen Zahlen)?",
    options: ["Gewinn sinkt, Steuerzahlung sinkt, Cash vor Steuern unverändert", "Gewinn sinkt, Steuerzahlung steigt", "Gewinn steigt, Cashflow sinkt", "Keine Auswirkung auf den Gewinn"],
    answer: 0,
    explain: "Abschreibung ist Aufwand ohne Auszahlung. Der Gewinn sinkt, damit auch die Ertragsteuer – unterm Strich bleibt sogar **mehr Cash** im Unternehmen (Steuerstundungseffekt)." },
  { id: "bw2-044", cat: "bwl", topic: "Abschreibungen", type: "truefalse", emoji: "🌍", level: 1,
    q: "Grundstücke werden planmäßig abgeschrieben.",
    answer: false,
    explain: "Grund und Boden nutzt sich nicht ab → **keine planmäßige Abschreibung**. Abgeschrieben wird nur das Gebäude darauf. Bei dauerhafter Wertminderung ist aber eine außerplanmäßige Abschreibung möglich." },

  // ── Rückstellungen ──
  { id: "bw2-045", cat: "bwl", topic: "Rückstellungen", type: "flashcard", emoji: "⚠️", level: 1,
    term: "Rückstellung",
    def: "**Fremdkapital** für Verpflichtungen, die dem Grunde nach bestehen, aber deren Höhe oder Fälligkeit noch ungewiss ist. Wird als Aufwand gebucht.",
    example: "Pensionszusagen, Garantieverpflichtungen, drohende Prozesskosten, ausstehende Steuernachzahlungen." },
  { id: "bw2-046", cat: "bwl", topic: "Rückstellungen", type: "flashcard", emoji: "🏛️", level: 1,
    term: "Rücklage",
    def: "**Eigenkapital**, das nicht im Grundkapital steckt: Kapitalrücklage (z. B. Agio bei Aktienausgabe) und Gewinnrücklagen (einbehaltene Gewinne).",
    example: "Merkhilfe: Rück**stellung** = Schuld, die man **stellt**; Rück**lage** = Gewinn, der **liegen** bleibt." },
  { id: "bw2-047", cat: "bwl", topic: "Rückstellungen", type: "quiz", emoji: "⚖️", level: 2,
    q: "Welcher Fall führt zu einer Rückstellung?",
    options: ["Einbehaltene Gewinne des Vorjahres", "Agio aus einer Kapitalerhöhung", "Geld, das für eine geplante Investition angespart wird", "Erwartete Kosten aus einem laufenden Rechtsstreit"],
    answer: 3,
    explain: "Der Rechtsstreit ist eine ungewisse Verbindlichkeit → **Rückstellung** (Fremdkapital). Einbehaltene Gewinne und Agio sind Rücklagen (Eigenkapital); „Ansparen“ ist gar keine Passivposition." },
  { id: "bw2-048", cat: "bwl", topic: "Rückstellungen", type: "truefalse", emoji: "🐷", level: 2,
    q: "Rücklagen sind ein Geldtopf, auf den das Unternehmen im Notfall zugreifen kann.",
    answer: false,
    explain: "Rücklagen stehen auf der Passivseite und zeigen nur die **Herkunft** von Kapital. Das Geld kann längst in Maschinen oder Vorräten stecken. Ob Cash da ist, zeigt allein die Aktivseite." },
  { id: "bw2-049", cat: "bwl", topic: "Rückstellungen", type: "whatif", emoji: "🛠️", level: 2,
    q: "Was passiert, wenn ein Hersteller eine Garantierückstellung von 1 Mio € bildet?",
    steps: ["Aufwand in der GuV: Gewinn −1 Mio €", "Passiva: Rückstellungen +1 Mio €", "Weniger Steuer und Ausschüttung", "Kein Geldabfluss – erst bei Inanspruchnahme"],
    text: "Rückstellungen ziehen künftige Lasten in die Gegenwart (**Vorsichtsprinzip**) und halten so Geld im Unternehmen, das sonst ausgeschüttet würde. Wird die Rückstellung nicht gebraucht, wird sie später ertragswirksam aufgelöst." },
  { id: "bw2-050", cat: "bwl", topic: "Rückstellungen", type: "number", emoji: "🏦", level: 3,
    value: "5 %", label: "des Jahresüberschusses in die gesetzliche Rücklage (AG)",
    text: "Nach § 150 AktG muss eine AG 5 % des (um einen Verlustvortrag geminderten) Jahresüberschusses in die gesetzliche Rücklage einstellen – bis diese zusammen mit bestimmten Kapitalrücklagen 10 % des Grundkapitals erreicht.",
    more: "Zweck: Gläubigerschutz – ein Teil des Gewinns darf nicht ausgeschüttet werden. Die GmbH kennt keine solche Pflicht; die UG (haftungsbeschränkt) muss dagegen 25 % ihres Jahresüberschusses zurücklegen." },

  // ── HGB vs. IFRS ──
  { id: "bw2-051", cat: "bwl", topic: "HGB & IFRS", type: "fact", emoji: "🛡️", level: 1,
    title: "Vorsichtsprinzip: Der Kaufmann rechnet sich arm",
    text: "Das HGB will Gläubiger schützen: Vermögen eher niedrig, Schulden eher hoch bewerten. Gewinne erst zeigen, wenn sie realisiert sind – Verluste schon, wenn sie drohen.",
    more: "Daraus folgen Realisations-, Imparitäts- und Niederstwertprinzip. Die IFRS stellen dagegen die **Information der Investoren** (fair presentation) in den Vordergrund und erlauben eher Zeitwerte (fair value) – also auch unrealisierte Gewinne." },
  { id: "bw2-052", cat: "bwl", topic: "HGB & IFRS", type: "flashcard", emoji: "🤝", level: 2,
    term: "Realisationsprinzip",
    def: "Gewinne dürfen erst ausgewiesen werden, wenn sie durch einen Umsatzakt realisiert sind – i. d. R. bei Lieferung bzw. Gefahrübergang, nicht bei Vertragsschluss oder Zahlung.",
    example: "Ein Grundstück verdoppelt seinen Marktwert: Nach HGB bleibt es zu Anschaffungskosten in der Bilanz, bis es verkauft wird." },
  { id: "bw2-053", cat: "bwl", topic: "HGB & IFRS", type: "flashcard", emoji: "⚖️", level: 3,
    term: "Imparitätsprinzip",
    def: "„Ungleichbehandlung“: Unrealisierte **Verluste** müssen schon erfasst werden, unrealisierte **Gewinne** nicht. Ausprägungen: Niederstwertprinzip (Aktiva) und Höchstwertprinzip (Passiva).",
    example: "Drohverlust aus einem schlecht kalkulierten Festpreisauftrag → Drohverlustrückstellung, obwohl noch nicht geliefert wurde." },
  { id: "bw2-054", cat: "bwl", topic: "HGB & IFRS", type: "quiz", emoji: "📦", level: 2,
    q: "Vorräte: Anschaffungskosten 10.000 €, Marktwert am Bilanzstichtag 8.000 €. Ansatz nach HGB?",
    options: ["10.000 €", "9.000 €", "8.000 €", "Wahlrecht zwischen 8.000 € und 10.000 €"],
    answer: 2,
    explain: "Im Umlaufvermögen gilt das **strenge Niederstwertprinzip**: Der niedrigere Wert ist zwingend anzusetzen → 8.000 €, 2.000 € Abschreibung als Aufwand." },
  { id: "bw2-055", cat: "bwl", topic: "HGB & IFRS", type: "truefalse", emoji: "🏗️", level: 3,
    q: "Im Anlagevermögen gilt nach HGB das strenge Niederstwertprinzip.",
    answer: false,
    explain: "Im Anlagevermögen gilt das **gemilderte** Niederstwertprinzip: Abschreibungspflicht nur bei voraussichtlich **dauernder** Wertminderung (bei Finanzanlagen Wahlrecht bei vorübergehender). Streng gilt es im Umlaufvermögen." },
  { id: "bw2-056", cat: "bwl", topic: "HGB & IFRS", type: "quiz", emoji: "🌐", level: 2,
    q: "Welches Ziel steht bei den IFRS im Vordergrund?",
    options: ["Entscheidungsnützliche Information für Investoren", "Bemessung der Steuerlast", "Gläubigerschutz durch vorsichtige Bewertung", "Begrenzung der Ausschüttung"],
    answer: 0,
    explain: "IFRS-Abschlüsse sollen Kapitalmarktteilnehmern ein den tatsächlichen Verhältnissen entsprechendes Bild geben. Pflicht für Konzernabschlüsse kapitalmarktorientierter EU-Unternehmen seit 2005. Steuer und Ausschüttung hängen am HGB-Einzelabschluss." },
  { id: "bw2-057", cat: "bwl", topic: "HGB & IFRS", type: "fact", emoji: "🏷️", level: 3,
    title: "Goodwill: abschreiben oder testen?",
    text: "Zahlt ein Käufer mehr als das Nettovermögen wert ist, entsteht ein **Geschäfts- oder Firmenwert**. HGB: planmäßige Abschreibung (im Zweifel über 10 Jahre). IFRS: keine planmäßige Abschreibung, sondern jährlicher **Impairment-Test**.",
    more: "Folge: IFRS-Konzerne zeigen nach Übernahmen zunächst höhere Gewinne – aber wenn der Deal floppt, kommt die Wertberichtigung oft als Milliarden-Knall auf einmal. Bilanzanalyse-Tipp: Goodwill im Verhältnis zum Eigenkapital prüfen." },
  { id: "bw2-058", cat: "bwl", topic: "HGB & IFRS", type: "truefalse", emoji: "🔬", level: 3,
    q: "Nach HGB dürfen selbst geschaffene Forschungskosten aktiviert werden.",
    answer: false,
    explain: "§ 248 Abs. 2 HGB: Für **Entwicklungskosten** selbst geschaffener immaterieller Vermögensgegenstände besteht ein Aktivierungswahlrecht – **Forschungskosten** dürfen nie aktiviert werden. Ist keine Trennung möglich, gilt alles als Aufwand." },
  { id: "bw2-059", cat: "bwl", topic: "HGB & IFRS", type: "quiz", emoji: "📈", level: 3,
    q: "Ein Wertpapier (Anschaffung 10.000 €) wurde auf 8.000 € abgeschrieben. Nun steigt der Kurs auf 12.000 €. Ansatz nach HGB?",
    options: ["8.000 €", "12.000 €", "Wahlrecht 8.000–12.000 €", "10.000 €"],
    answer: 3,
    explain: "Fällt der Grund der Abschreibung weg, gilt das **Wertaufholungsgebot** (§ 253 Abs. 5 HGB) – aber maximal bis zu den **Anschaffungskosten** (10.000 €). Die 2.000 € darüber sind unrealisierter Gewinn." },
  { id: "bw2-060", cat: "bwl", topic: "HGB & IFRS", type: "fact", emoji: "🚚", level: 3,
    title: "IFRS 16: Leasing kommt in die Bilanz",
    text: "Seit 2019 bilanzieren Leasingnehmer nach IFRS fast alle Leasingverträge: **Nutzungsrecht** (Aktiva) und **Leasingverbindlichkeit** (Passiva). Statt Leasingaufwand fallen Abschreibung und Zinsaufwand an.",
    more: "Nebenwirkung: Das **EBITDA steigt** (Leasingrate verschwindet aus dem operativen Aufwand), gleichzeitig steigen Bilanzsumme und Nettoverschuldung. Beim Vergleich von Kennzahlen vor und nach 2019 – oder HGB vs. IFRS – unbedingt beachten." },
  { id: "bw2-061", cat: "bwl", topic: "HGB & IFRS", type: "whatif", emoji: "💥", level: 3,
    q: "Was passiert, wenn ein IFRS-Konzern den Goodwill einer gescheiterten Übernahme abschreibt?",
    steps: ["Impairment-Aufwand in der GuV", "Konzernergebnis bricht ein", "Eigenkapital sinkt, Cash bleibt unverändert", "EK-Quote und ggf. Covenants unter Druck"],
    text: "Das Geld ist schon beim Kauf geflossen – die Abschreibung macht den Fehlkauf nur sichtbar. Deshalb ist ein Impairment nicht zahlungswirksam, sagt aber viel über die Qualität früherer Akquisitionsentscheidungen." },

  // ── Jahresabschluss ──
  { id: "bw2-062", cat: "bwl", topic: "Jahresabschluss", type: "order", emoji: "🗓️", level: 2,
    q: "Bringe die Schritte bei einer prüfungspflichtigen GmbH in die richtige Reihenfolge.",
    items: ["Aufstellung durch die Geschäftsführung", "Prüfung durch den Abschlussprüfer", "Feststellung durch die Gesellschafter", "Offenlegung im Unternehmensregister"],
    explain: "Die Geschäftsführung stellt auf, der Prüfer prüft, die Gesellschafterversammlung stellt fest (macht ihn verbindlich) und beschließt über die Gewinnverwendung, dann folgt die Offenlegung." },
  { id: "bw2-063", cat: "bwl", topic: "Jahresabschluss", type: "flashcard", emoji: "📚", level: 1,
    term: "Bestandteile des Jahresabschlusses",
    def: "Alle Kaufleute: Bilanz + GuV. Kapitalgesellschaften zusätzlich: **Anhang**. Mittelgroße und große Kapitalgesellschaften außerdem einen **Lagebericht** (formal kein Teil des Abschlusses).",
    example: "Kapitalmarktorientierte Unternehmen ohne Konzernabschlusspflicht ergänzen Kapitalflussrechnung und Eigenkapitalspiegel." },
  { id: "bw2-064", cat: "bwl", topic: "Jahresabschluss", type: "quiz", emoji: "🔎", level: 2,
    q: "Welches Unternehmen ist nach HGB nicht prüfungspflichtig?",
    options: ["Kleine GmbH", "Mittelgroße GmbH", "Große AG", "Börsennotierte AG"],
    answer: 0,
    explain: "§ 316 HGB: Prüfungspflicht für **mittelgroße und große** Kapitalgesellschaften. Kleine Kapitalgesellschaften (gemessen an Bilanzsumme, Umsatz, Mitarbeitern) sind befreit." },
  { id: "bw2-065", cat: "bwl", topic: "Jahresabschluss", type: "fact", emoji: "✅", level: 2,
    title: "Bestätigungsvermerk: das Prüfer-Testat",
    text: "Der Abschlussprüfer erteilt einen **uneingeschränkten**, einen **eingeschränkten** Bestätigungsvermerk oder einen **Versagungsvermerk**. Schon eine Einschränkung ist für Banken und Investoren ein Alarmsignal.",
    more: "Warnbeispiel Wirecard (2020): Jahrelang uneingeschränkte Testate, dann fehlten 1,9 Mrd € angebliche Treuhandguthaben. Folge u. a. das FISG 2021 mit strengerer Prüferrotation und schärferer Haftung." },
  { id: "bw2-066", cat: "bwl", topic: "Jahresabschluss", type: "truefalse", emoji: "🕵️", level: 2,
    q: "Ein uneingeschränkter Bestätigungsvermerk garantiert, dass im Unternehmen kein Betrug stattgefunden hat.",
    answer: false,
    explain: "Die Prüfung gibt nur **hinreichende Sicherheit**, dass der Abschluss frei von wesentlichen Fehlern ist – sie arbeitet mit Stichproben und Wesentlichkeitsgrenzen. Sie ist keine Unterschlagungsprüfung." },

  // ── Kennzahlen ──
  { id: "bw2-067", cat: "bwl", topic: "Kennzahlen", type: "flashcard", emoji: "📏", level: 1,
    term: "EBIT",
    def: "Earnings Before Interest and Taxes – Ergebnis vor Zinsen und Steuern. Misst die **operative Ertragskraft**, unabhängig von Finanzierung und Steuersitz.",
    example: "Zwei Firmen mit gleichem Geschäft, eine schuldenfrei, eine hoch verschuldet: gleiches EBIT, aber sehr unterschiedlicher Jahresüberschuss." },
  { id: "bw2-068", cat: "bwl", topic: "Kennzahlen", type: "flashcard", emoji: "🧼", level: 2,
    term: "EBITDA",
    def: "EBIT plus Abschreibungen (Depreciation & Amortization). Näherung für den operativen Cash-Ertrag und Basis für Bewertungs-Multiples und Kredit-Covenants.",
    example: "Kritik (Warren Buffett): Abschreibungen sind echte Kosten – irgendwer muss die Maschinen ja ersetzen. Kapitalintensive Firmen sehen per EBITDA zu gut aus." },
  { id: "bw2-069", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "🧮", level: 1,
    q: "Gewinn 60.000 €, Umsatz 1,2 Mio €. Wie hoch ist die Umsatzrendite?",
    options: ["2 %", "5 %", "12 %", "20 %"],
    answer: 1,
    explain: "60.000 / 1.200.000 = **5 %**. Von jedem Euro Umsatz bleiben 5 Cent Gewinn." },
  { id: "bw2-070", cat: "bwl", topic: "Kennzahlen", type: "fact", emoji: "🌳", level: 2,
    title: "DuPont: ROI = Umsatzrendite × Kapitalumschlag",
    text: "Der ROI (Gewinn / Gesamtkapital) lässt sich zerlegen: **Gewinn/Umsatz × Umsatz/Kapital**. Zwei Wege zu 10 % ROI: 10 % Marge × 1,0 (Luxusmarke) oder 2 % Marge × 5,0 (Discounter).",
    more: "Das DuPont-Schema (1919 beim Chemiekonzern DuPont entwickelt) ist ein Kennzahlenbaum: Man kann jeden Ast weiter aufbrechen (Kostenstruktur, Vorräte, Forderungen) und sieht so, wo genau Rendite verloren geht." },
  { id: "bw2-071", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "🌳", level: 2,
    q: "Umsatzrendite 4 %, Kapitalumschlag 2,5. Wie hoch ist der ROI?",
    options: ["6,5 %", "1,6 %", "10 %", "16 %"],
    answer: 2,
    explain: "DuPont: 4 % × 2,5 = **10 %**." },
  { id: "bw2-072", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "🧱", level: 1,
    q: "Eigenkapital 300.000 €, Bilanzsumme 1,2 Mio €. Eigenkapitalquote?",
    options: ["25 %", "30 %", "33 %", "40 %"],
    answer: 0,
    explain: "300.000 / 1.200.000 = **25 %**. Je höher, desto krisenfester und unabhängiger von Banken – aber zu viel EK kann die EK-Rendite verwässern." },
  { id: "bw2-073", cat: "bwl", topic: "Kennzahlen", type: "fact", emoji: "🏋️", level: 3,
    title: "Leverage-Effekt: Schulden als Renditehebel",
    text: "**rEK = rGK + (rGK − i) × FK/EK.** Solange die Gesamtkapitalrendite über dem Fremdkapitalzins liegt, steigert jeder zusätzliche Euro Schulden die Eigenkapitalrendite.",
    more: "Der Hebel wirkt in beide Richtungen: Fällt die Gesamtkapitalrendite unter den Zins, frisst er das Eigenkapital (**Leverage-Risiko**). Genau so funktionieren Private-Equity-Buyouts – und so gehen sie schief, wenn Zinsen steigen." },
  { id: "bw2-074", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "🏋️", level: 3,
    q: "Gesamtkapitalrendite 8 %, FK-Zins 4 %, Verschuldungsgrad FK/EK = 2. Eigenkapitalrendite?",
    options: ["12 %", "8 %", "20 %", "16 %"],
    answer: 3,
    explain: "rEK = 8 % + (8 % − 4 %) × 2 = 8 % + 8 % = **16 %** (vor Steuern)." },
  { id: "bw2-075", cat: "bwl", topic: "Kennzahlen", type: "whatif", emoji: "📈", level: 3,
    q: "Was passiert, wenn bei einem hoch verschuldeten Unternehmen die Zinsen über die Gesamtkapitalrendite steigen?",
    steps: ["Spread rGK − i wird negativ", "Hebel wirkt jetzt gegen den Eigentümer", "EK-Rendite fällt unter die GK-Rendite", "Verluste zehren Eigenkapital auf"],
    text: "Das **Leverage-Risiko**: Beispiel rGK 6 %, i 8 %, FK/EK 3 → rEK = 6 % − 2 % × 3 = 0 %. Je höher der Verschuldungsgrad, desto brutaler der Absturz." },
  { id: "bw2-076", cat: "bwl", topic: "Kennzahlen", type: "flashcard", emoji: "💧", level: 2,
    term: "Liquiditätsgrade 1–3",
    def: "Jeweils geteilt durch kurzfristige Verbindlichkeiten: 1. Grad = flüssige Mittel; 2. Grad (Quick Ratio) = + kurzfristige Forderungen; 3. Grad (Current Ratio) = gesamtes Umlaufvermögen.",
    example: "Faustregeln: 2. Grad ≥ 100 %, 3. Grad ≥ 120–200 %. Ein zu hoher 1. Grad heißt: Geld liegt unverzinst herum." },
  { id: "bw2-077", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "💧", level: 2,
    q: "Flüssige Mittel 50.000 €, kurzfristige Forderungen 100.000 €, Vorräte 120.000 €, kurzfristige Verbindlichkeiten 200.000 €. Liquidität 2. Grades?",
    options: ["25 %", "135 %", "75 %", "60 %"],
    answer: 2,
    explain: "(50.000 + 100.000) / 200.000 = **75 %** – unter der Faustregel von 100 %. Vorräte zählen erst beim 3. Grad (dann 135 %)." },
  { id: "bw2-078", cat: "bwl", topic: "Kennzahlen", type: "flashcard", emoji: "🔄", level: 2,
    term: "Working Capital",
    def: "Umlaufvermögen minus kurzfristige Verbindlichkeiten. Operativ oft enger: **Vorräte + Forderungen aLuL − Verbindlichkeiten aLuL** (Net Working Capital).",
    example: "Jeder Euro Working Capital ist gebundenes Kapital. Working-Capital-Management (schneller kassieren, weniger Lager, später zahlen) setzt Cash frei, ohne einen Euro mehr Umsatz." },
  { id: "bw2-079", cat: "bwl", topic: "Kennzahlen", type: "flashcard", emoji: "⏱️", level: 3,
    term: "DSO · DIO · DPO",
    def: "Days Sales Outstanding (Forderungen/Umsatz × 365), Days Inventory Outstanding (Vorräte/Materialaufwand bzw. Umsatzkosten × 365), Days Payables Outstanding (Verbindlichkeiten/Materialaufwand × 365).",
    example: "Merkhilfe: S = Sales (Kunden), I = Inventory (Lager), P = Payables (Lieferanten)." },
  { id: "bw2-080", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "🧾", level: 2,
    q: "Forderungen aLuL 1 Mio €, Jahresumsatz 7,3 Mio €. Wie hoch ist der DSO?",
    options: ["73 Tage", "50 Tage", "30 Tage", "14 Tage"],
    answer: 1,
    explain: "1 / 7,3 × 365 = **50 Tage**. Im Schnitt warten Sie 50 Tage auf Ihr Geld." },
  { id: "bw2-081", cat: "bwl", topic: "Kennzahlen", type: "fact", emoji: "🔁", level: 3,
    title: "Cash Conversion Cycle = DSO + DIO − DPO",
    text: "Der CCC misst, wie viele Tage zwischen der Bezahlung des Lieferanten und dem Geldeingang vom Kunden liegen. So lange muss das Unternehmen sein operatives Geschäft **vorfinanzieren**.",
    more: "Ein negativer CCC ist der Traum jedes CFOs: Kunden zahlen sofort, Lieferanten später – Wachstum finanziert sich selbst. Klassisches Beispiel sind Online-Händler und Supermärkte mit schnell drehender Ware und langen Lieferantenzielen." },
  { id: "bw2-082", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "🔁", level: 3,
    q: "DSO 40 Tage, DIO 50 Tage, DPO 30 Tage. Wie lang ist der Cash Conversion Cycle?",
    options: ["120 Tage", "20 Tage", "40 Tage", "60 Tage"],
    answer: 3,
    explain: "40 + 50 − 30 = **60 Tage** Finanzierungslücke." },
  { id: "bw2-083", cat: "bwl", topic: "Kennzahlen", type: "whatif", emoji: "🤝", level: 2,
    q: "Was passiert, wenn ein Unternehmen bei Lieferanten 30 statt 15 Tage Zahlungsziel durchsetzt?",
    steps: ["DPO steigt um 15 Tage", "Cash Conversion Cycle sinkt", "Working Capital sinkt, Cash wird frei", "Lieferanten finanzieren mit (ggf. Skonto weg)"],
    text: "Einmaliger Liquiditätseffekt: Bei 3,65 Mio € Materialaufwand pro Jahr setzen 15 Tage etwa 150.000 € frei. Aber Achtung: Wer dafür auf Skonto verzichtet, zahlt einen sehr teuren Kredit." },
  { id: "bw2-084", cat: "bwl", topic: "Kennzahlen", type: "truefalse", emoji: "🎭", level: 2,
    q: "Eine hohe Eigenkapitalrendite ist immer ein Zeichen für ein gut geführtes Unternehmen.",
    answer: false,
    explain: "Eine hohe EK-Rendite kann auch aus einer **sehr dünnen Eigenkapitaldecke** (Leverage) stammen – oder aus Aktienrückkäufen auf Pump. Immer zusammen mit Verschuldung und Gesamtkapitalrendite lesen." },
  { id: "bw2-085", cat: "bwl", topic: "Kennzahlen", type: "number", emoji: "🥇", level: 2,
    value: "≥ 100 %", label: "Anlagendeckungsgrad II (Goldene Bilanzregel)",
    text: "(Eigenkapital + langfristiges Fremdkapital) / Anlagevermögen sollte mindestens 100 % betragen: Langfristig gebundenes Vermögen soll langfristig finanziert sein.",
    more: "Hintergrund ist die **Fristenkongruenz**: Wer eine Fabrik mit Kontokorrentkredit finanziert, ist bei jeder Kreditkürzung erpressbar. Deckungsgrad I (nur EK / AV) erreichen viele gesunde Firmen nicht – das ist kein Drama." },
  { id: "bw2-086", cat: "bwl", topic: "Kennzahlen", type: "quiz", emoji: "💹", level: 1,
    q: "Jahresüberschuss 50.000 €, Eigenkapital 250.000 €. Eigenkapitalrendite (ROE)?",
    options: ["5 %", "12,5 %", "25 %", "20 %"],
    answer: 3,
    explain: "50.000 / 250.000 = **20 %**. Vergleichsmaßstab: Was hätte der Eigentümer mit vergleichbarem Risiko anderswo verdient (Opportunitätskosten)?" },
  { id: "bw2-087", cat: "bwl", topic: "Kennzahlen", type: "truefalse", emoji: "📜", level: 1,
    q: "EBITDA ist eine im HGB definierte Pflichtkennzahl.",
    answer: false,
    explain: "EBIT und EBITDA sind **nicht gesetzlich definiert** – jedes Unternehmen kann sie etwas anders berechnen („adjusted EBITDA“). Deshalb beim Vergleich immer die Überleitung prüfen." },

  // ── Kostenrechnung ──
  { id: "bw2-088", cat: "bwl", topic: "Kostenrechnung", type: "order", emoji: "🧭", level: 1,
    q: "Ordne die drei Stufen der klassischen Kostenrechnung.",
    items: ["Kostenartenrechnung: Welche Kosten sind angefallen?", "Kostenstellenrechnung: Wo sind sie angefallen?", "Kostenträgerrechnung: Wofür sind sie angefallen?"],
    explain: "Erst erfassen (**Was?**), dann auf Abteilungen verteilen (**Wo?**, z. B. mit dem BAB), dann den Produkten zurechnen (**Wofür?**) – Basis für Kalkulation und Preisentscheidungen." },
  { id: "bw2-089", cat: "bwl", topic: "Kostenrechnung", type: "flashcard", emoji: "🧱", level: 1,
    term: "Fixe vs. variable Kosten",
    def: "Fixe Kosten bleiben bei schwankender Ausbringung (kurzfristig) gleich – Miete, Gehälter, Versicherungen. Variable Kosten ändern sich mit der Menge – Material, Stückakkord, Energie der Maschinen.",
    example: "Pizzeria: Ofenmiete fix, Mehl und Käse variabel. Je mehr Pizzen, desto weniger Fixkosten pro Pizza (Fixkostendegression)." },
  { id: "bw2-090", cat: "bwl", topic: "Kostenrechnung", type: "flashcard", emoji: "🎯", level: 1,
    term: "Einzelkosten vs. Gemeinkosten",
    def: "Einzelkosten lassen sich einem Produkt direkt zurechnen (Fertigungsmaterial, Akkordlohn). Gemeinkosten fallen für mehrere Produkte gemeinsam an und müssen per Schlüssel verteilt werden (Hallenmiete, Verwaltung).",
    example: "Achtung: Das ist eine andere Dimension als fix/variabel – Zurechenbarkeit vs. Mengenabhängigkeit." },
  { id: "bw2-091", cat: "bwl", topic: "Kostenrechnung", type: "truefalse", emoji: "⚡", level: 2,
    q: "Gemeinkosten sind immer fixe Kosten.",
    answer: false,
    explain: "Der Stromverbrauch einer Halle, in der mehrere Produkte laufen, ist **variabel**, aber nicht einem einzelnen Produkt zurechenbar → variable Gemeinkosten. Zurechenbarkeit und Mengenabhängigkeit sind zwei getrennte Fragen." },
  { id: "bw2-092", cat: "bwl", topic: "Kostenrechnung", type: "fact", emoji: "➕", level: 1,
    title: "Deckungsbeitrag: Was jedes Stück zur Deckung beiträgt",
    text: "**Stück-DB = Preis − variable Stückkosten.** Dieser Betrag deckt erst die Fixkosten; sind sie gedeckt, ist jeder weitere DB Gewinn. Gesamt-DB − Fixkosten = Betriebsergebnis.",
    more: "Warum wichtig: Für kurzfristige Entscheidungen (Zusatzauftrag, Sortiment, Engpass) zählt der DB, nicht der Vollkostengewinn. Ein Produkt mit „Verlust“ in der Vollkostenrechnung, aber positivem DB, sollte man kurzfristig nicht streichen – sonst müssen die anderen seine Fixkosten tragen." },
  { id: "bw2-093", cat: "bwl", topic: "Kostenrechnung", type: "quiz", emoji: "⚖️", level: 1,
    q: "Fixkosten 100.000 €, Preis 50 €, variable Stückkosten 30 €. Wo liegt der Break-even?",
    options: ["2.000 Stück", "3.333 Stück", "5.000 Stück", "10.000 Stück"],
    answer: 2,
    explain: "Break-even = Fixkosten / Stück-DB = 100.000 / (50 − 30) = **5.000 Stück**." },
  { id: "bw2-094", cat: "bwl", topic: "Kostenrechnung", type: "whatif", emoji: "🏢", level: 1,
    q: "Was passiert, wenn die Fixkosten steigen (z. B. neue, teurere Halle)?",
    steps: ["Stück-DB bleibt gleich", "Mehr Stück nötig, um Fixkosten zu decken", "Break-even-Menge steigt", "Sicherheitsabstand zur Ist-Menge sinkt"],
    text: "Break-even = Fixkosten / DB. Steigen die Fixkosten um 20 %, steigt die Break-even-Menge ebenfalls um 20 %. Hohe Fixkosten machen ein Unternehmen anfälliger für Absatzeinbrüche (**operating leverage**)." },
  { id: "bw2-095", cat: "bwl", topic: "Kostenrechnung", type: "quiz", emoji: "🏷️", level: 2,
    q: "Fixkosten 100.000 €, variable Stückkosten 30 €. Der Preis sinkt von 50 € auf 45 €. Neuer Break-even?",
    options: ["5.000 Stück", "6.667 Stück", "5.556 Stück", "4.000 Stück"],
    answer: 1,
    explain: "DB sinkt von 20 € auf 15 € → 100.000 / 15 = **6.667 Stück**. 10 % Preissenkung → 33 % mehr Absatz nötig! Preissenkungen sind teurer, als sie aussehen." },
  { id: "bw2-096", cat: "bwl", topic: "Kostenrechnung", type: "quiz", emoji: "📬", level: 2,
    q: "Freie Kapazität. Variable Stückkosten 30 €, Vollkosten 45 €. Ein Kunde bietet 35 € pro Stück für einen Zusatzauftrag. Was tun?",
    options: ["Ablehnen: Preis unter Vollkosten", "Ablehnen: Preis muss mindestens 45 € sein", "Nur annehmen, wenn er 50 € zahlt", "Annehmen: +5 € DB pro Stück"],
    answer: 3,
    explain: "Die Fixkosten fallen ohnehin an. Kurzfristig zählt nur: Preis > variable Kosten → **5 € DB je Stück**, der Gewinn steigt. Risiko: Stammkunden erfahren vom Preis." },
  { id: "bw2-097", cat: "bwl", topic: "Kostenrechnung", type: "flashcard", emoji: "📉", level: 2,
    term: "Preisuntergrenze kurz- vs. langfristig",
    def: "Kurzfristig: **variable Stückkosten** – darüber bringt jedes Stück einen positiven DB. Langfristig: **Vollkosten** (fix + variabel pro Stück) – sonst zehrt das Unternehmen seine Substanz auf.",
    example: "Airline in der Nebensaison: Ein Ticket für 39 € deckt Kerosin und Gebühren pro Passagier; das Flugzeug fliegt eh." },
  { id: "bw2-098", cat: "bwl", topic: "Kostenrechnung", type: "quiz", emoji: "🍾", level: 3,
    q: "Engpass: Maschinenzeit. A: DB 40 €, 4 Min. · B: DB 30 €, 2 Min. · C: DB 24 €, 3 Min. Welches Produkt zuerst fertigen?",
    options: ["A – höchster absoluter DB", "C – mittlere Fertigungszeit", "B – höchster DB pro Engpassminute", "Alle gleichmäßig"],
    answer: 2,
    explain: "Bei Engpass zählt der **relative Deckungsbeitrag**: A 10 €/Min, B **15 €/Min**, C 8 €/Min. Reihenfolge: B → A → C." },
  { id: "bw2-099", cat: "bwl", topic: "Kostenrechnung", type: "quiz", emoji: "🧮", level: 2,
    q: "Materialeinzelkosten 100 €, MGK-Zuschlag 20 %, Fertigungseinzelkosten 50 €, FGK-Zuschlag 100 %. Herstellkosten?",
    options: ["170 €", "220 €", "270 €", "200 €"],
    answer: 1,
    explain: "Materialkosten 100 + 20 = 120; Fertigungskosten 50 + 50 = 100. Herstellkosten = **220 €**." },
  { id: "bw2-100", cat: "bwl", topic: "Kostenrechnung", type: "order", emoji: "🏷️", level: 2,
    q: "Ordne die Stufen der Zuschlagskalkulation (Vorwärtskalkulation).",
    items: ["Herstellkosten", "Selbstkosten", "Barverkaufspreis", "Zielverkaufspreis", "Listenverkaufspreis"],
    explain: "HK + Verwaltungs- und Vertriebsgemeinkosten = **Selbstkosten**; + Gewinnzuschlag = **Barverkaufspreis**; + Kundenskonto = **Zielverkaufspreis**; + Kundenrabatt = **Listenverkaufspreis** (netto)." },
  { id: "bw2-101", cat: "bwl", topic: "Kostenrechnung", type: "fact", emoji: "⚙️", level: 3,
    title: "Prozesskostenrechnung: Gemeinkosten nach Aktivität",
    text: "Statt Gemeinkosten pauschal per Prozent auf Einzelkosten zu schlagen, verteilt die Prozesskostenrechnung sie nach **Kostentreibern**: Anzahl Bestellungen, Rüstvorgänge, Varianten, Reklamationen.",
    more: "Aha-Effekt: Exoten und Kleinaufträge sind oft viel teurer, als die Zuschlagskalkulation zeigt – sie verursachen überproportional Rüsten, Disposition und Logistik. Die Großserie subventioniert sie unbemerkt. Entwickelt u. a. von Kaplan/Cooper als Activity-Based Costing." },
  { id: "bw2-102", cat: "bwl", topic: "Kostenrechnung", type: "flashcard", emoji: "📋", level: 3,
    term: "Betriebsabrechnungsbogen (BAB)",
    def: "Tabelle der Kostenstellenrechnung: verteilt Gemeinkosten per Schlüssel auf Kostenstellen (Material, Fertigung, Verwaltung, Vertrieb), verrechnet Hilfskostenstellen und liefert die **Zuschlagssätze**.",
    example: "Fertigungsgemeinkosten 500.000 € / Fertigungslöhne 250.000 € → FGK-Zuschlag 200 %." },
  { id: "bw2-103", cat: "bwl", topic: "Kostenrechnung", type: "quiz", emoji: "🛠️", level: 2,
    q: "Make-or-Buy, kurzfristig, freie Kapazität: Eigenfertigung variabel 18 €/Stück, anteilige Fixkosten 10 €/Stück (bleiben ohnehin). Fremdbezug 22 €. Entscheidung?",
    options: ["Selbst fertigen: 18 € < 22 €", "Zukaufen: 22 € < 28 €", "Egal, Kosten identisch", "Zukaufen, um Fixkosten zu sparen"],
    answer: 0,
    explain: "Die Fixkosten bleiben bei Zukauf bestehen → nicht entscheidungsrelevant. Relevante Kosten der Eigenfertigung: 18 € < 22 € → **selbst fertigen**. Langfristig (Fixkosten abbaubar) sieht es anders aus." },
  { id: "bw2-104", cat: "bwl", topic: "Kostenrechnung", type: "flashcard", emoji: "🤔", level: 1,
    term: "Opportunitätskosten – die unsichtbaren Kosten",
    def: "Der entgangene Nutzen der besten nicht gewählten Alternative. Fließen in keine Buchhaltung ein, gehören aber in jede gute Entscheidung.",
    example: "Ein Gründer verzichtet auf 80.000 € Gehalt im Konzern. Macht sein Startup 50.000 € Gewinn, hat er ökonomisch 30.000 € „verloren“." },
  { id: "bw2-105", cat: "bwl", topic: "Kostenrechnung", type: "truefalse", emoji: "🕳️", level: 2,
    q: "Bereits ausgegebenes Geld für ein Projekt (Sunk Costs) sollte bei der Entscheidung über dessen Fortführung berücksichtigt werden.",
    answer: false,
    explain: "Versunkene Kosten sind unwiederbringlich – sie ändern sich durch keine Entscheidung. Relevant sind nur **künftige** Zahlungen. Der Drang „sonst war alles umsonst“ ist die Sunk-Cost-Falle (Concorde-Effekt)." },
  { id: "bw2-106", cat: "bwl", topic: "Kostenrechnung", type: "fact", emoji: "🔀", level: 2,
    title: "Vollkosten vs. Teilkosten",
    text: "**Vollkostenrechnung** verteilt alle Kosten auf die Produkte – nötig für langfristige Preise und die Bewertung von Beständen. **Teilkostenrechnung** (Deckungsbeitragsrechnung) rechnet nur variable Kosten zu – besser für kurzfristige Entscheidungen.",
    more: "Typischer Fehler: Mit Vollkosten-Stückkosten kurzfristig entscheiden. Weil die Fixkosten pro Stück von der Menge abhängen, führt das zu falschen Ablehnungen von Aufträgen und zu Sortimentsbereinigungen, die das Ergebnis verschlechtern." },
  { id: "bw2-107", cat: "bwl", topic: "Kostenrechnung", type: "flashcard", emoji: "🪝", level: 3,
    term: "Kostenremanenz",
    def: "Kosten sinken bei Rückgang der Beschäftigung langsamer, als sie beim Anstieg gestiegen sind – wegen Kündigungsfristen, Verträgen, Zögern des Managements.",
    example: "Umsatz −20 %, Kosten nur −8 %: Die Marge bricht stärker ein als der Umsatz." },
  { id: "bw2-108", cat: "bwl", topic: "Kostenrechnung", type: "flashcard", emoji: "📶", level: 2,
    term: "Sprungfixe Kosten",
    def: "Fixkosten, die innerhalb eines Bereichs konstant sind, bei Überschreiten einer Kapazitätsgrenze aber sprunghaft steigen.",
    example: "Ein Lkw schafft 20 Touren am Tag. Bei der 21. Tour braucht man einen zweiten Lkw plus Fahrer." },
  { id: "bw2-109", cat: "bwl", topic: "Kostenrechnung", type: "whatif", emoji: "🌀", level: 3,
    q: "Was passiert, wenn eine Firma bei sinkendem Absatz die Preise per Vollkostenkalkulation anpasst?",
    steps: ["Weniger Menge → Fixkosten je Stück steigen", "Kalkulierter Preis wird erhöht", "Kunden kaufen noch weniger", "Stückkosten steigen erneut"],
    text: "Die **Todesspirale der Vollkostenkalkulation**: Wer Fixkosten auf eine schrumpfende Menge umlegt und den Preis daran knüpft, kalkuliert sich aus dem Markt. Ausweg: Preise am Markt und am Deckungsbeitrag orientieren." },
  { id: "bw2-110", cat: "bwl", topic: "Kostenrechnung", type: "quiz", emoji: "🪵", level: 1,
    q: "Welche Kosten sind bei einer Möbelschreinerei typischerweise variabel?",
    options: ["Holz für die Möbel", "Miete der Werkstatt", "Gehalt des Meisters", "Kfz-Versicherung"],
    answer: 0,
    explain: "Das **Holz** steigt mit jeder produzierten Einheit. Miete, Meistergehalt und Versicherung fallen unabhängig von der Stückzahl an." },
  { id: "bw2-111", cat: "bwl", topic: "Kostenrechnung", type: "whatif", emoji: "✂️", level: 2,
    q: "Was passiert, wenn ein Produkt mit Vollkostenverlust, aber positivem Deckungsbeitrag gestrichen wird?",
    steps: ["Umsatz und DB des Produkts entfallen", "Die zugeschlüsselten Fixkosten bleiben", "Andere Produkte tragen mehr Fixkosten", "Gesamtergebnis sinkt"],
    text: "Beispiel: Produkt C hat 50.000 € DB, aber 80.000 € zugeschlüsselte Fixkosten → scheinbar −30.000 €. Streicht man es, fehlen 50.000 € Deckung – das Ergebnis wird um 50.000 € schlechter, solange die Fixkosten nicht abbaubar sind." },

  // ── Controlling ──
  { id: "bw2-112", cat: "bwl", topic: "Controlling", type: "fact", emoji: "🧭", level: 1,
    title: "Controlling heißt steuern, nicht kontrollieren",
    text: "Vom englischen „to control“ = steuern, lenken. Controller planen mit, messen, vergleichen Soll und Ist, analysieren Abweichungen und schlagen Maßnahmen vor – als **betriebswirtschaftliches Gewissen** des Managements.",
    more: "Abgrenzung: Die Interne Revision prüft rückblickend Ordnungsmäßigkeit, das Controlling blickt nach vorn. Der Controller entscheidet nicht selbst, sondern sorgt für Transparenz – die Verantwortung bleibt beim Management." },
  { id: "bw2-113", cat: "bwl", topic: "Controlling", type: "order", emoji: "🔄", level: 1,
    q: "Ordne den Controlling-Regelkreis.",
    items: ["Ziele und Plan festlegen (Soll)", "Umsetzen", "Ergebnisse messen (Ist)", "Soll-Ist-Vergleich und Abweichungsanalyse", "Gegensteuern bzw. Plan anpassen"],
    explain: "Ein klassischer Regelkreis (PDCA-ähnlich). Wichtig: Erst die Ursachenanalyse macht aus einer Abweichung eine Steuerungsinformation." },
  { id: "bw2-114", cat: "bwl", topic: "Controlling", type: "flashcard", emoji: "🗂️", level: 2,
    term: "Balanced Scorecard",
    def: "Kennzahlensystem von Kaplan/Norton (1992), das Strategie in Ziele übersetzt – in vier Perspektiven: **Finanzen, Kunden, interne Prozesse, Lernen & Entwicklung**.",
    example: "Ziel „Kundenbindung“: KPI Wiederkaufrate, Zielwert 60 %, Maßnahme Loyalty-Programm. Die vier Perspektiven sind über Ursache-Wirkungs-Ketten verbunden." },
  { id: "bw2-115", cat: "bwl", topic: "Controlling", type: "quiz", emoji: "🗂️", level: 2,
    q: "Welche ist **keine** der vier klassischen Perspektiven der Balanced Scorecard?",
    options: ["Kundenperspektive", "Lern- und Entwicklungsperspektive", "Interne Prozessperspektive", "Wettbewerberperspektive"],
    answer: 3,
    explain: "Die vier Perspektiven: Finanzen, Kunden, interne Prozesse, Lernen & Entwicklung. Unternehmen dürfen sie anpassen, der Wettbewerb ist aber kein Standardbestandteil." },
  { id: "bw2-116", cat: "bwl", topic: "Controlling", type: "flashcard", emoji: "↕️", level: 2,
    term: "Gegenstromverfahren",
    def: "Budgetierung in zwei Richtungen: Die Leitung gibt Rahmenziele vor (top-down), die Bereiche planen detailliert und melden zurück (bottom-up), dann wird abgestimmt.",
    example: "Verbindet Strategiekonformität (top-down) mit Realismus und Motivation (bottom-up). In der Praxis der häufigste Ansatz." },
  { id: "bw2-117", cat: "bwl", topic: "Controlling", type: "flashcard", emoji: "0️⃣", level: 3,
    term: "Zero-Based Budgeting",
    def: "Jedes Budget startet bei null und muss komplett neu begründet werden – statt das Vorjahr fortzuschreiben (inkrementelle Budgetierung).",
    example: "Deckt historisch gewachsene „Budgetpolster“ auf, ist aber sehr aufwendig. Bekannt geworden durch harte Kostenprogramme nach Übernahmen (z. B. bei 3G Capital/Kraft Heinz)." },
  { id: "bw2-118", cat: "bwl", topic: "Controlling", type: "quiz", emoji: "📊", level: 2,
    q: "Marketingbudget 200.000 €, Ist-Ausgaben 230.000 €. Abweichung in Prozent des Budgets?",
    options: ["+13 %", "+30 %", "+15 %", "+23 %"],
    answer: 2,
    explain: "(230.000 − 200.000) / 200.000 = **+15 %**. Bezugsgröße ist immer das Soll (Budget)." },
  { id: "bw2-119", cat: "bwl", topic: "Controlling", type: "truefalse", emoji: "🔍", level: 3,
    q: "Die flexible Plankostenrechnung trennt die Gesamtabweichung u. a. in Verbrauchs- und Beschäftigungsabweichung.",
    answer: true,
    explain: "**Beschäftigungsabweichung**: Fixkosten werden bei abweichender Menge falsch verrechnet (nicht der Kostenstelle anzulasten). **Verbrauchsabweichung**: Ist-Kosten vs. Sollkosten bei Ist-Menge – die echte Wirtschaftlichkeitsfrage." },
  { id: "bw2-120", cat: "bwl", topic: "Controlling", type: "truefalse", emoji: "📟", level: 1,
    q: "Je mehr KPIs ein Management-Dashboard enthält, desto besser lässt sich das Unternehmen steuern.",
    answer: false,
    explain: "Zu viele KPIs verwässern den Fokus. Gute KPIs sind wenige, steuerbar, mit Strategie verknüpft und haben einen Verantwortlichen. Und: Was gemessen wird, wird optimiert – auch auf Kosten von Nicht-Gemessenem (Goodhart's Law)." },

  // ── Investition ──
  { id: "bw2-121", cat: "bwl", topic: "Investition", type: "fact", emoji: "⏳", level: 1,
    title: "Ein Euro heute ist mehr wert als ein Euro morgen",
    text: "Weil man Geld heute anlegen kann, müssen künftige Zahlungen **abgezinst** (diskontiert) werden: Barwert = Zahlung / (1 + i)^t. Das ist die Grundidee aller dynamischen Investitionsrechnungen.",
    more: "Umkehrung: Aufzinsen (Endwert = K × (1 + i)^t). Merke: Je höher der Zins und je weiter in der Zukunft, desto weniger ist eine Zahlung heute wert. Deshalb reagieren lang laufende Projekte (und Wachstumsaktien) besonders stark auf Zinsänderungen." },
  { id: "bw2-122", cat: "bwl", topic: "Investition", type: "quiz", emoji: "🧮", level: 2,
    q: "Welchen Barwert haben 1.000 €, die in 2 Jahren gezahlt werden, bei 5 % Zins?",
    options: ["900,00 €", "952,38 €", "907,03 €", "1.102,50 €"],
    answer: 2,
    explain: "1.000 / 1,05² = 1.000 / 1,1025 = **907,03 €**. (952,38 € wäre nur ein Jahr, 1.102,50 € der Endwert.)" },
  { id: "bw2-123", cat: "bwl", topic: "Investition", type: "flashcard", emoji: "🎯", level: 2,
    term: "Kapitalwert (NPV)",
    def: "Summe aller abgezinsten Ein- und Auszahlungen eines Projekts, inklusive Anfangsinvestition. NPV > 0 → Projekt verdient mehr als den Kalkulationszins und schafft Wert.",
    example: "NPV = −I₀ + Σ CFₜ / (1 + i)ᵗ. Bei sich ausschließenden Projekten wählt man das mit dem höchsten NPV." },
  { id: "bw2-124", cat: "bwl", topic: "Investition", type: "quiz", emoji: "🧮", level: 2,
    q: "Investition 1.000 €, Rückflüsse je 600 € am Ende von Jahr 1 und 2, Zins 10 %. Kapitalwert?",
    options: ["+200,00 €", "+41,32 €", "−41,32 €", "+90,91 €"],
    answer: 1,
    explain: "600/1,1 = 545,45; 600/1,21 = 495,87; Summe 1.041,32 − 1.000 = **+41,32 €**. Positiv → lohnt sich." },
  { id: "bw2-125", cat: "bwl", topic: "Investition", type: "flashcard", emoji: "🎚️", level: 2,
    term: "Interner Zinsfuß (IRR)",
    def: "Der Zinssatz, bei dem der Kapitalwert genau null ist – die „Rendite“ des Projekts. Lohnend, wenn IRR > Kapitalkosten (Hurdle Rate).",
    example: "Investition 1.000 €, in einem Jahr 1.100 € zurück → IRR = 10 %. Bei mehreren Perioden meist nur iterativ (Excel: IRR/IKV) lösbar." },
  { id: "bw2-126", cat: "bwl", topic: "Investition", type: "truefalse", emoji: "🌀", level: 3,
    q: "Der interne Zinsfuß ist für jedes Investitionsprojekt eindeutig bestimmbar.",
    answer: false,
    explain: "Wechselt die Zahlungsreihe **mehrfach das Vorzeichen** (z. B. Rückbaukosten am Ende), kann es mehrere oder gar keinen IRR geben. Außerdem unterstellt die Methode Wiederanlage zum IRR – ein Grund, im Zweifel dem NPV zu folgen." },
  { id: "bw2-127", cat: "bwl", topic: "Investition", type: "quiz", emoji: "⏱️", level: 1,
    q: "Eine Anlage kostet 100.000 € und bringt jährlich 25.000 € Rückfluss. Statische Amortisationsdauer?",
    options: ["2,5 Jahre", "5 Jahre", "25 Jahre", "4 Jahre"],
    answer: 3,
    explain: "100.000 / 25.000 = **4 Jahre**. Einfach zu verstehen – deshalb in der Praxis beliebt, v. a. als Risikomaß." },
  { id: "bw2-128", cat: "bwl", topic: "Investition", type: "truefalse", emoji: "🙈", level: 2,
    q: "Die statische Amortisationsrechnung berücksichtigt auch die Rückflüsse nach dem Amortisationszeitpunkt.",
    answer: false,
    explain: "Sie fragt nur: Wann ist das Geld zurück? Alles danach wird **ignoriert** – ebenso der Zeitwert des Geldes. Projekt A (Payback 3 J., danach nichts) schlägt so fälschlich Projekt B (Payback 4 J., danach 10 Jahre Gewinne)." },
  { id: "bw2-129", cat: "bwl", topic: "Investition", type: "flashcard", emoji: "🔁", level: 3,
    term: "Annuität",
    def: "Verwandelt einen Kapitalwert in eine gleichbleibende jährliche Zahlung über die Laufzeit: Annuität = NPV × Annuitätenfaktor (Wiedergewinnungsfaktor).",
    example: "Annuitätenfaktor = i(1+i)ⁿ / ((1+i)ⁿ − 1). Bei 10 % und 2 Jahren ≈ 0,5762 → NPV 41,32 € ≈ 23,81 € Überschuss pro Jahr. Praktisch beim Vergleich von Projekten mit unterschiedlicher Laufzeit." },
  { id: "bw2-130", cat: "bwl", topic: "Investition", type: "fact", emoji: "⚖️", level: 3,
    title: "WACC: der Mindestzins eines Unternehmens",
    text: "**WACC = EK/GK × rEK + FK/GK × rFK × (1 − s).** Die gewichteten Kapitalkosten sind die Hürde, die Investitionen überspringen müssen, um für Eigen- und Fremdkapitalgeber Wert zu schaffen.",
    more: "Das (1 − s) ist der **Tax Shield**: Zinsen mindern die Steuer, deshalb ist Fremdkapital netto billiger. Die Eigenkapitalkosten schätzt man meist per CAPM: risikoloser Zins + Beta × Marktrisikoprämie. Gewichtung idealerweise zu Marktwerten." },
  { id: "bw2-131", cat: "bwl", topic: "Investition", type: "quiz", emoji: "🧮", level: 3,
    q: "60 % EK zu 10 %, 40 % FK zu 5 %, Steuersatz 30 %. WACC?",
    options: ["7,4 %", "8,0 %", "6,2 %", "7,0 %"],
    answer: 0,
    explain: "0,6 × 10 % = 6,0 %; 0,4 × 5 % × 0,7 = 1,4 % → **7,4 %**. Ohne Tax Shield wären es 8,0 %." },
  { id: "bw2-132", cat: "bwl", topic: "Investition", type: "whatif", emoji: "📈", level: 2,
    q: "Was passiert, wenn die Marktzinsen deutlich steigen?",
    steps: ["Kapitalkosten (WACC) steigen", "Künftige Cashflows werden stärker abgezinst", "Kapitalwerte sinken, manche werden negativ", "Weniger Projekte werden umgesetzt"],
    text: "Deshalb dämpfen Zinserhöhungen die Investitionstätigkeit – ein Hauptkanal der Geldpolitik. Besonders betroffen: Projekte mit späten Rückflüssen (Immobilien, Infrastruktur, Startups)." },
  { id: "bw2-133", cat: "bwl", topic: "Investition", type: "order", emoji: "🪜", level: 2,
    q: "Ordne die Schritte einer Kapitalwertberechnung.",
    items: ["Zahlungsreihe schätzen (Auszahlungen, Rückflüsse)", "Kalkulationszins festlegen (z. B. WACC)", "Alle Zahlungen auf t = 0 abzinsen", "Barwerte summieren, Investition abziehen", "Entscheiden: NPV > 0 → durchführen"],
    explain: "Der heikelste Schritt ist der erste: Die Rechnung ist nur so gut wie die Cashflow-Prognose. Deshalb gehören Sensitivitäts- und Szenarioanalysen dazu." },
  { id: "bw2-134", cat: "bwl", topic: "Investition", type: "number", emoji: "✌️", level: 1,
    value: "72", label: "Die Faustregel für Verdopplung",
    text: "72 / Zinssatz ≈ Jahre bis zur Verdopplung. Bei 6 % rund 12 Jahre, bei 8 % rund 9 Jahre.",
    more: "Funktioniert auch rückwärts mit Inflation: Bei 3 % Inflation halbiert sich die Kaufkraft in etwa 24 Jahren. Am genauesten ist die Regel im Bereich von etwa 6–10 %." },
  { id: "bw2-135", cat: "bwl", topic: "Investition", type: "quiz", emoji: "🥊", level: 2,
    q: "Zwei sich ausschließende Projekte: A hat IRR 25 % und NPV 1 Mio €, B hat IRR 15 % und NPV 3 Mio €. Welches wählen?",
    options: ["B, weil der NPV höher ist", "A, weil der IRR höher ist", "Beide, weil beide lohnen", "Keines, die Methoden widersprechen sich"],
    answer: 0,
    explain: "Der **NPV** misst den absoluten Wertzuwachs in Euro. Ein hoher IRR auf ein kleines Projekt schafft weniger Wert. Bei Konflikten gilt: NPV schlägt IRR." },

  // ── Finanzierung ──
  { id: "bw2-136", cat: "bwl", topic: "Finanzierung", type: "flashcard", emoji: "🧭", level: 1,
    term: "Innen- vs. Außenfinanzierung",
    def: "Außen: Kapital kommt von außen (Einlagen, Kredite, Anleihen). Innen: Kapital entsteht aus dem Umsatzprozess (einbehaltene Gewinne, Abschreibungs- und Rückstellungsgegenwerte, Vermögensverkauf).",
    example: "Zweite Achse: Eigen- vs. Fremdfinanzierung (Rechtsstellung des Geldgebers). Daraus ergibt sich eine 2×2-Matrix." },
  { id: "bw2-137", cat: "bwl", topic: "Finanzierung", type: "quiz", emoji: "🔲", level: 1,
    q: "Ein Unternehmen behält seinen Gewinn ein, statt ihn auszuschütten. Welche Finanzierungsform ist das?",
    options: ["Außen- und Fremdfinanzierung", "Außen- und Eigenfinanzierung", "Innen- und Fremdfinanzierung", "Innen- und Eigenfinanzierung"],
    answer: 3,
    explain: "**Selbstfinanzierung**: Das Geld stammt aus dem Umsatzprozess (innen) und erhöht das Eigenkapital (eigen). Rückstellungsfinanzierung wäre dagegen Innen- und Fremdfinanzierung." },
  { id: "bw2-138", cat: "bwl", topic: "Finanzierung", type: "fact", emoji: "🔥", level: 1,
    title: "Skonto ziehen schlägt fast jeden Kredit",
    text: "„2 % Skonto bei Zahlung in 10 Tagen, sonst 30 Tage netto“ klingt nach wenig. Wer nicht zieht, zahlt aber 2 % für **20 Tage** Aufschub – auf das Jahr gerechnet rund **36 % Zins**.",
    more: "Faustformel: Skontosatz × 360 / (Zahlungsziel − Skontofrist) = 2 × 360 / 20 = 36 %. Exakt: 2/98 × 360/20 ≈ 36,7 %. Daher: Skonto lieber per Kontokorrentkredit (z. B. 10 %) finanzieren – das lohnt sich fast immer." },
  { id: "bw2-139", cat: "bwl", topic: "Finanzierung", type: "quiz", emoji: "🧮", level: 2,
    q: "Rechnung 10.000 €: 2 % Skonto innerhalb 10 Tagen, netto 30 Tage. Ihr Kontokorrentzins: 12 % p. a. Lohnt es sich, Skonto per Kredit zu ziehen?",
    options: ["Ja: Kredit für 20 Tage kostet ca. 65 €, Skonto bringt 200 €", "Nein, 12 % Zinsen sind zu teuer", "Nein, Skonto bringt nur 20 €", "Egal, beides kostet gleich viel"],
    answer: 0,
    explain: "Kredit: 9.800 € × 12 % × 20/360 ≈ **65 €**. Skontoertrag: **200 €**. Ersparnis ≈ 135 €. Der Lieferantenkredit (≈ 36,7 % p. a.) ist viel teurer als der Bankkredit." },
  { id: "bw2-140", cat: "bwl", topic: "Finanzierung", type: "quiz", emoji: "🧮", level: 3,
    q: "Zahlungsbedingung: 3 % Skonto innerhalb 14 Tagen, Zahlungsziel 45 Tage. Effektiver Jahreszins des Lieferantenkredits (360 Tage)?",
    options: ["ca. 3 %", "ca. 24 %", "ca. 35,9 %", "ca. 77 %"],
    answer: 2,
    explain: "Kreditdauer 45 − 14 = 31 Tage. 3/97 × 360/31 = 0,0309 × 11,61 ≈ **35,9 %**. (Faustformel 3 × 360/31 ≈ 34,8 %.)" },
  { id: "bw2-141", cat: "bwl", topic: "Finanzierung", type: "flashcard", emoji: "🤝", level: 2,
    term: "Lieferantenkredit",
    def: "Der Lieferant gewährt ein Zahlungsziel – formlos, ohne Bonitätsprüfung im Bankstil, aber mit Eigentumsvorbehalt. Der Preis steckt im verlorenen Skonto.",
    example: "Bequem und schnell verfügbar – deshalb das am häufigsten genutzte, aber oft teuerste kurzfristige Fremdkapital im Mittelstand." },
  { id: "bw2-142", cat: "bwl", topic: "Finanzierung", type: "flashcard", emoji: "📨", level: 2,
    term: "Factoring",
    def: "Verkauf von Forderungen an einen Factor gegen sofortige Zahlung (abzüglich Gebühren). Beim **echten** Factoring trägt der Factor das Ausfallrisiko (Delkredere), beim **unechten** bleibt es beim Verkäufer.",
    example: "Funktionen: Finanzierung (sofort Liquidität), Delkredere (Ausfallschutz), Service (Debitorenbuchhaltung, Mahnwesen)." },
  { id: "bw2-143", cat: "bwl", topic: "Finanzierung", type: "whatif", emoji: "📨", level: 3,
    q: "Was passiert, wenn ein Unternehmen seine Forderungen per echtem Factoring verkauft?",
    steps: ["Forderungen ↓, Bank ↑ (Aktivtausch)", "DSO sinkt, Cash sofort verfügbar", "Mit dem Cash Schulden tilgen → Bilanz kürzer", "EK-Quote ↑, Gebühr mindert Gewinn"],
    text: "Echtes Factoring verbessert Liquidität und Bilanzbild – ein Grund, warum es auch zur „Bilanzkosmetik“ zum Stichtag genutzt wird. Kosten: Zins plus Gebühr, typischerweise im Bereich weniger Prozent des Forderungsvolumens." },
  { id: "bw2-144", cat: "bwl", topic: "Finanzierung", type: "flashcard", emoji: "🚜", level: 2,
    term: "Leasing & Sale-and-Lease-Back",
    def: "Leasing: Nutzung eines Wirtschaftsguts gegen Raten, Eigentum beim Leasinggeber. Sale-and-Lease-Back: Das Unternehmen verkauft eigene Anlagen und mietet sie zurück → einmaliger Liquiditätszufluss.",
    example: "Handelsketten verkaufen oft ihre Filialimmobilien und leasen sie zurück, um Expansion zu finanzieren." },
  { id: "bw2-145", cat: "bwl", topic: "Finanzierung", type: "truefalse", emoji: "🧾", level: 2,
    q: "Leasing ist grundsätzlich günstiger als ein kreditfinanzierter Kauf.",
    answer: false,
    explain: "Der Leasinggeber muss seine Finanzierung, sein Risiko und seine Marge einpreisen. Leasing kann Vorteile bei Liquidität, Service und Flexibilität bringen – die Gesamtkosten sind aber oft **höher**. Immer per Barwertvergleich prüfen." },
  { id: "bw2-146", cat: "bwl", topic: "Finanzierung", type: "flashcard", emoji: "🥪", level: 3,
    term: "Mezzanine-Kapital",
    def: "Hybride Finanzierung zwischen Eigen- und Fremdkapital: nachrangig gegenüber Bankkrediten, aber vorrangig vor echtem Eigenkapital. Teurer als Kredit, günstiger als EK, meist ohne Stimmrechte.",
    example: "Nachrangdarlehen, stille Beteiligung, Genussrechte, Wandel- und Optionsanleihen. Banken werten es oft als „wirtschaftliches Eigenkapital“." },
  { id: "bw2-147", cat: "bwl", topic: "Finanzierung", type: "quiz", emoji: "🥪", level: 3,
    q: "Welches Instrument ist **kein** Mezzanine-Kapital?",
    options: ["Nachrangdarlehen", "Stille Beteiligung", "Genussrechte", "Stammaktie"],
    answer: 3,
    explain: "Die **Stammaktie** ist reines Eigenkapital mit Stimmrecht und voller Verlustbeteiligung. Die anderen drei liegen in der Rangfolge zwischen Kredit und Eigenkapital." },
  { id: "bw2-148", cat: "bwl", topic: "Finanzierung", type: "flashcard", emoji: "📜", level: 3,
    term: "Covenants",
    def: "Auflagen in Kreditverträgen. **Financial Covenants** setzen Kennzahlengrenzen (z. B. Nettoverschuldung/EBITDA ≤ 3,0; EK-Quote ≥ 30 %). Bei Bruch erhält die Bank Sonderrechte bis zur Kündigung.",
    example: "Auch nicht-finanzielle Covenants: keine Dividende ohne Zustimmung, keine weiteren Sicherheiten an Dritte (Negativerklärung)." },
  { id: "bw2-149", cat: "bwl", topic: "Finanzierung", type: "whatif", emoji: "🚨", level: 3,
    q: "Was passiert, wenn ein Unternehmen einen Financial Covenant bricht?",
    steps: ["Bank erhält außerordentliches Kündigungsrecht", "Nachverhandlung: Waiver gegen Gebühr", "Höherer Zins, mehr Sicherheiten", "Extremfall: Fälligstellung, Insolvenz"],
    text: "Meist wird nicht gekündigt, sondern neu verhandelt – aber die Verhandlungsmacht liegt dann bei der Bank. Deshalb planen CFOs ausreichend **Headroom** zu den Covenant-Grenzen ein." },
  { id: "bw2-150", cat: "bwl", topic: "Finanzierung", type: "order", emoji: "🦄", level: 2,
    q: "Ordne die typischen Phasen der Venture-Capital-Finanzierung.",
    items: ["Seed (Idee, Prototyp)", "Early Stage / Series A (Markteintritt)", "Growth / Expansion (Skalierung)", "Exit (IPO oder Trade Sale)"],
    explain: "Mit jeder Runde steigt meist die Bewertung, das Risiko sinkt. Der VC-Fonds verdient erst beim **Exit** – durch Verkauf seiner Anteile." },
  { id: "bw2-151", cat: "bwl", topic: "Finanzierung", type: "truefalse", emoji: "🎰", level: 2,
    q: "Venture-Capital-Fonds sind darauf angewiesen, dass wenige Beteiligungen extrem erfolgreich sind, weil viele scheitern.",
    answer: true,
    explain: "Die Renditen folgen einem **Power Law**: Ein bis zwei Treffer tragen oft den ganzen Fonds. Deshalb investieren VCs nur in Firmen, die theoretisch das 10-Fache und mehr erreichen können – und erwarten aggressives Wachstum." },
  { id: "bw2-152", cat: "bwl", topic: "Finanzierung", type: "fact", emoji: "🧷", level: 2,
    title: "Fristenkongruenz: Langes Geld für lange Anlagen",
    text: "Die **goldene Finanzierungsregel**: Kapital soll mindestens so lange zur Verfügung stehen, wie es im Vermögen gebunden ist. Eine Maschine mit 10 Jahren Nutzung gehört nicht auf den Dispo.",
    more: "Wer langfristige Investitionen kurzfristig finanziert, trägt Prolongations- und Zinsänderungsrisiko. Klassischer Fall des Verstoßes: Banken in der Finanzkrise 2008, die langfristige Kredite über kurzfristige Geldmarktmittel refinanzierten." },
  { id: "bw2-153", cat: "bwl", topic: "Finanzierung", type: "flashcard", emoji: "♻️", level: 3,
    term: "Lohmann-Ruchti-Effekt",
    def: "Kapazitätserweiterungseffekt: Abschreibungsgegenwerte fließen über die Umsatzerlöse zurück und werden sofort reinvestiert. So wächst der Maschinenpark ohne neues Kapital.",
    example: "Grenzen: Er setzt voraus, dass die Abschreibungen verdient werden, die Preise stabil bleiben und mehr Kapazität auch abgesetzt wird." },
  { id: "bw2-154", cat: "bwl", topic: "Finanzierung", type: "truefalse", emoji: "🛡️", level: 1,
    q: "Fremdkapitalzinsen mindern grundsätzlich die steuerliche Bemessungsgrundlage, Dividenden an Eigentümer nicht.",
    answer: true,
    explain: "Daher der **Tax Shield** des Fremdkapitals. Grenzen: Zinsschranke (Abzug begrenzt auf 30 % des steuerlichen EBITDA, sofern die Freigrenze überschritten ist) und die teilweise Hinzurechnung von Zinsen bei der Gewerbesteuer." },
  { id: "bw2-155", cat: "bwl", topic: "Finanzierung", type: "fact", emoji: "🆘", level: 2,
    title: "Drei Insolvenzgründe",
    text: "**Zahlungsunfähigkeit** und **Überschuldung** verpflichten Geschäftsführer einer GmbH zum Insolvenzantrag. **Drohende Zahlungsunfähigkeit** berechtigt nur zum Eigenantrag.",
    more: "Fristen (Stand 2025): Antrag spätestens 3 Wochen nach Zahlungsunfähigkeit, 6 Wochen nach Überschuldung. Verschleppung ist strafbar und führt zu persönlicher Haftung. Merke: Pleite geht man fast immer an fehlender Liquidität, nicht am Bilanzverlust." },
  { id: "bw2-156", cat: "bwl", topic: "Finanzierung", type: "order", emoji: "🪜", level: 3,
    q: "Insolvenz: Ordne, wer typischerweise zuerst aus dem Vermögen bedient wird.",
    items: ["Gesicherte Gläubiger (aus ihren Sicherheiten)", "Massegläubiger (Verfahrenskosten, Masseverbindlichkeiten)", "Ungesicherte Insolvenzgläubiger (Quote)", "Nachrangige Gläubiger (z. B. Gesellschafterdarlehen)", "Gesellschafter (Eigenkapital)"],
    explain: "Daher die Preisunterschiede: Besichertes Fremdkapital ist billig, Nachrang und Eigenkapital teuer. Ungesicherte Gläubiger erhalten oft nur eine einstellige Quote, Eigentümer meist nichts." },

  // ── Unternehmensbewertung ──
  { id: "bw2-157", cat: "bwl", topic: "Bewertung", type: "flashcard", emoji: "🔮", level: 3,
    term: "Discounted Cashflow (DCF)",
    def: "Unternehmenswert = Barwert aller künftigen Free Cashflows, abgezinst mit dem WACC. Meist: 3–5 Jahre Detailplanung plus Restwert (Terminal Value) für die Zeit danach.",
    example: "Ergebnis ist der Enterprise Value; minus Nettofinanzschulden = Wert des Eigenkapitals." },
  { id: "bw2-158", cat: "bwl", topic: "Bewertung", type: "flashcard", emoji: "✖️", level: 2,
    term: "Multiples",
    def: "Bewertung über Vergleich mit ähnlichen Unternehmen oder Transaktionen: z. B. EV/EBITDA, EV/Umsatz, KGV. Schnell und marktnah, aber nur so gut wie die Vergleichsgruppe.",
    example: "Branchen-Multiple 8× EBITDA, eigenes EBITDA 5 Mio € → Enterprise Value ≈ 40 Mio €." },
  { id: "bw2-159", cat: "bwl", topic: "Bewertung", type: "quiz", emoji: "🧮", level: 2,
    q: "EBITDA 10 Mio €, Multiple 8× EV/EBITDA, Nettofinanzschulden 20 Mio €. Wert des Eigenkapitals?",
    options: ["80 Mio €", "100 Mio €", "60 Mio €", "28 Mio €"],
    answer: 2,
    explain: "Enterprise Value = 8 × 10 = 80 Mio €. Equity Value = 80 − 20 = **60 Mio €**. Typischer Fehler: EV mit Kaufpreis für die Anteile verwechseln." },
  { id: "bw2-160", cat: "bwl", topic: "Bewertung", type: "quiz", emoji: "♾️", level: 3,
    q: "Free Cashflow im ersten Jahr nach der Detailplanung 10 Mio €, WACC 8 %, ewiges Wachstum 2 %. Terminal Value (Gordon)?",
    options: ["125 Mio €", "166,7 Mio €", "500 Mio €", "100 Mio €"],
    answer: 1,
    explain: "TV = FCF / (WACC − g) = 10 / (0,08 − 0,02) = 10 / 0,06 = **166,7 Mio €** (Wert zum Ende der Detailplanung, muss noch abgezinst werden)." },
  { id: "bw2-161", cat: "bwl", topic: "Bewertung", type: "truefalse", emoji: "🏔️", level: 3,
    q: "In vielen DCF-Bewertungen macht der Terminal Value mehr als die Hälfte des Unternehmenswerts aus.",
    answer: true,
    explain: "Oft sogar deutlich mehr – bei Wachstumsunternehmen der Großteil. Deshalb entscheiden die Annahmen zu WACC und ewiger Wachstumsrate stärker über den Wert als die sorgfältig geplanten Detailjahre." },
  { id: "bw2-162", cat: "bwl", topic: "Bewertung", type: "fact", emoji: "🌉", level: 2,
    title: "Enterprise Value vs. Equity Value",
    text: "Der **Enterprise Value** ist der Wert des operativen Geschäfts für alle Kapitalgeber. **Equity Value = Enterprise Value − Nettofinanzschulden.** Nur der Equity Value gehört den Aktionären.",
    more: "Bild: Ein Haus (EV) für 500.000 € mit 300.000 € Hypothek – Ihr Anteil (Equity) ist 200.000 €. Deshalb passen EV-Multiples (EV/EBITDA) zu Größen vor Zinsen, Equity-Multiples (KGV) zu Größen nach Zinsen." },
  { id: "bw2-163", cat: "bwl", topic: "Bewertung", type: "whatif", emoji: "📉", level: 3,
    q: "Was passiert mit dem Terminal Value, wenn der WACC von 8 % auf 9 % steigt (g = 2 %, FCF 10 Mio €)?",
    steps: ["Nenner WACC − g: 6 % → 7 %", "TV: 166,7 → 142,9 Mio €", "Ein Prozentpunkt kostet ca. 14 % Wert", "Gesamtwert sinkt deutlich"],
    text: "Kleine Änderungen der Annahmen bewegen DCF-Werte stark. Deshalb zeigen Bewertungsgutachten immer eine **Sensitivitätsmatrix** (WACC × Wachstumsrate) statt eines einzigen Werts." },

  // ── Steuern ──
  { id: "bw2-164", cat: "bwl", topic: "Unternehmenssteuern", type: "number", emoji: "🏛️", level: 1,
    value: "15 %", label: "Körperschaftsteuer in Deutschland (Stand 2025)",
    text: "Kapitalgesellschaften (GmbH, AG) zahlen 15 % Körperschaftsteuer auf ihren Gewinn, dazu 5,5 % Solidaritätszuschlag darauf → **15,825 %**.",
    more: "2025 wurde eine schrittweise Senkung um je einen Prozentpunkt ab 2028 auf 10 % im Jahr 2032 beschlossen. Hinzu kommt immer die Gewerbesteuer der Gemeinde – erst zusammen ergibt sich die Gesamtbelastung." },
  { id: "bw2-165", cat: "bwl", topic: "Unternehmenssteuern", type: "fact", emoji: "🏘️", level: 2,
    title: "Gewerbesteuer: Messbetrag × Hebesatz",
    text: "Gewerbeertrag × **3,5 %** Steuermesszahl = Steuermessbetrag. Dieser × **Hebesatz** der Gemeinde (mindestens 200 %) = Gewerbesteuer. Bei 400 % Hebesatz also 14 % des Gewerbeertrags.",
    more: "Der Gewerbeertrag ist der Gewinn plus Hinzurechnungen (u. a. 25 % der Finanzierungsentgelte über einem Freibetrag) minus Kürzungen. Einzelunternehmen und Personengesellschaften haben einen Freibetrag von 24.500 € – Kapitalgesellschaften nicht." },
  { id: "bw2-166", cat: "bwl", topic: "Unternehmenssteuern", type: "quiz", emoji: "🧮", level: 2,
    q: "GmbH, Gewerbeertrag 100.000 €, Hebesatz 400 %. Wie hoch ist die Gewerbesteuer?",
    options: ["3.500 €", "14.000 €", "4.000 €", "10.570 €"],
    answer: 1,
    explain: "100.000 × 3,5 % = 3.500 € Messbetrag; × 400 % = **14.000 €**. Bei der GmbH gibt es keinen Freibetrag." },
  { id: "bw2-167", cat: "bwl", topic: "Unternehmenssteuern", type: "number", emoji: "🧾", level: 2,
    value: "≈ 30 %", label: "Ertragsteuerbelastung einer GmbH",
    text: "15,825 % (KSt + Soli) + 14 % Gewerbesteuer (bei 400 % Hebesatz) ≈ **29,8 %**. Je nach Gemeinde liegt die Belastung etwa zwischen 23 % und 33 % (Stand 2025).",
    more: "Für den WACC rechnet man daher in Deutschland oft mit 30 % Steuersatz. Bei Ausschüttung kommt beim Gesellschafter noch Abgeltungsteuer (25 % + Soli) bzw. das Teileinkünfteverfahren hinzu – erst dann ist die Gesamtlast vergleichbar mit dem Einzelunternehmer." },
  { id: "bw2-168", cat: "bwl", topic: "Unternehmenssteuern", type: "quiz", emoji: "🧮", level: 1,
    q: "Eine Rechnung lautet über 238 € brutto (19 % USt). Wie hoch ist die enthaltene Umsatzsteuer?",
    options: ["45,22 €", "19,00 €", "38,00 €", "40,46 €"],
    answer: 2,
    explain: "Netto = 238 / 1,19 = 200 € → USt = **38 €**. Typischer Fehler: 19 % vom Bruttobetrag rechnen (45,22 €)." },
  { id: "bw2-169", cat: "bwl", topic: "Unternehmenssteuern", type: "fact", emoji: "🔄", level: 1,
    title: "Umsatzsteuer ist ein durchlaufender Posten",
    text: "Unternehmen kassieren USt vom Kunden und führen sie ans Finanzamt ab – minus der **Vorsteuer**, die sie selbst an Lieferanten gezahlt haben. Belastet wird am Ende nur der Endverbraucher.",
    more: "Deshalb taucht die USt beim vorsteuerabzugsberechtigten Unternehmen nicht als Aufwand in der GuV auf. Jede Stufe versteuert nur ihre **Wertschöpfung** (Mehrwertsteuer). Achtung Liquidität: Die USt-Vorauszahlung wird fällig, auch wenn der Kunde noch nicht gezahlt hat (Soll-Versteuerung)." },
  { id: "bw2-170", cat: "bwl", topic: "Unternehmenssteuern", type: "quiz", emoji: "🧮", level: 2,
    q: "Ein Händler verkauft Waren für 10.000 € netto und hat für 6.000 € netto eingekauft (jeweils 19 %). Umsatzsteuer-Zahllast?",
    options: ["1.900 €", "1.140 €", "3.040 €", "760 €"],
    answer: 3,
    explain: "USt 1.900 € − Vorsteuer 1.140 € = **760 €** = 19 % auf die Wertschöpfung von 4.000 €." },
  { id: "bw2-171", cat: "bwl", topic: "Unternehmenssteuern", type: "truefalse", emoji: "📚", level: 1,
    q: "Für Bücher und die meisten Lebensmittel gilt in Deutschland der ermäßigte Umsatzsteuersatz von 7 %.",
    answer: true,
    explain: "Regelsatz 19 %, ermäßigt 7 % u. a. für die meisten Lebensmittel, Bücher, Zeitungen und den ÖPNV-Nahverkehr. Ausnahmen gibt es viele (z. B. Getränke wie Saft und Mineralwasser: 19 %)." },
  { id: "bw2-172", cat: "bwl", topic: "Unternehmenssteuern", type: "truefalse", emoji: "🎁", level: 2,
    q: "Der Gewerbesteuer-Freibetrag von 24.500 € gilt auch für GmbHs.",
    answer: false,
    explain: "Der Freibetrag gilt nur für **natürliche Personen und Personengesellschaften** (§ 11 GewStG). Kapitalgesellschaften zahlen ab dem ersten Euro Gewerbeertrag." },
  { id: "bw2-173", cat: "bwl", topic: "Unternehmenssteuern", type: "flashcard", emoji: "🐣", level: 2,
    term: "Kleinunternehmerregelung (Stand 2025)",
    def: "Keine Umsatzsteuer, wenn der Umsatz im Vorjahr ≤ 25.000 € war und im laufenden Jahr 100.000 € nicht übersteigt (§ 19 UStG). Dafür auch kein Vorsteuerabzug.",
    example: "Lohnt sich bei Privatkunden (Preise wirken 19 % günstiger) – bei Geschäftskunden meist nicht, da diese die USt ohnehin abziehen könnten." },
  { id: "bw2-174", cat: "bwl", topic: "Unternehmenssteuern", type: "truefalse", emoji: "🚫", level: 3,
    q: "Die Gewerbesteuer darf als Betriebsausgabe vom Gewinn abgezogen werden.",
    answer: false,
    explain: "Seit der Unternehmensteuerreform 2008 ist die Gewerbesteuer **keine Betriebsausgabe** mehr. Zum Ausgleich wurde die Messzahl auf 3,5 % gesenkt. Einzelunternehmer erhalten stattdessen eine Anrechnung auf die Einkommensteuer." },
  { id: "bw2-175", cat: "bwl", topic: "Unternehmenssteuern", type: "quiz", emoji: "👤", level: 3,
    q: "Einzelunternehmer können die Gewerbesteuer pauschal auf ihre Einkommensteuer anrechnen. Mit welchem Faktor auf den Messbetrag (Stand 2025)?",
    options: ["4,0", "1,8", "3,8", "2,5"],
    answer: 0,
    explain: "Seit 2020 das **4,0-Fache** des Messbetrags (§ 35 EStG), begrenzt auf die tatsächlich gezahlte GewSt. Bis zu einem Hebesatz von 400 % wird die GewSt so weitgehend neutralisiert." },
  { id: "bw2-176", cat: "bwl", topic: "Unternehmenssteuern", type: "whatif", emoji: "🗺️", level: 2,
    q: "Was passiert, wenn eine Gemeinde ihren Gewerbesteuer-Hebesatz deutlich senkt?",
    steps: ["Steuerlast für Unternehmen sinkt", "Firmen verlagern Sitz oder Holdings", "Steuerbasis der Gemeinde wächst", "Nachbargemeinden verlieren Einnahmen"],
    text: "Der Standortwettbewerb ist real: Kommunen mit niedrigen Hebesätzen (z. B. Monheim am Rhein) zogen viele Holdinggesellschaften an. Deshalb gibt es den Mindesthebesatz von 200 %." },
  { id: "bw2-177", cat: "bwl", topic: "Unternehmenssteuern", type: "flashcard", emoji: "↪️", level: 3,
    term: "Verlustvortrag",
    def: "Verluste eines Jahres mindern die Steuer künftiger Gewinne. Die **Mindestbesteuerung** begrenzt das: Bis 1 Mio € Gewinn voll verrechenbar, darüber nur zu einem Teil – der Rest wird später genutzt.",
    example: "Startup mit 3 Mio € Anfangsverlusten zahlt in den ersten Gewinnjahren kaum Ertragsteuer. Verlustvorträge sind daher ein Vermögenswert (latente Steuern)." },
  { id: "bw2-178", cat: "bwl", topic: "Unternehmenssteuern", type: "order", emoji: "🧾", level: 2,
    q: "Ordne die Schritte zur Berechnung der Gewerbesteuer.",
    items: ["Gewinn aus Gewerbebetrieb", "± Hinzurechnungen und Kürzungen = Gewerbeertrag", "× 3,5 % Steuermesszahl = Messbetrag", "× Hebesatz der Gemeinde = Gewerbesteuer"],
    explain: "Bei Einzelunternehmen und Personengesellschaften wird vor der Messzahl noch der Freibetrag von 24.500 € abgezogen (Stand 2025)." },

  // ── Produktion ──
  { id: "bw2-179", cat: "bwl", topic: "Produktion", type: "fact", emoji: "📦", level: 2,
    title: "Andler-Formel: die optimale Bestellmenge",
    text: "**Q* = √(2 × Jahresbedarf × Kosten pro Bestellung / Lagerkosten pro Stück und Jahr).** Sie balanciert zwei Kosten: Viele kleine Bestellungen kosten Bestellaufwand, wenige große binden Lager.",
    more: "Im Optimum sind Bestell- und Lagerhaltungskosten gleich hoch. Annahmen: konstanter Bedarf, keine Mengenrabatte, keine Fehlmengen. Die Kostenkurve ist im Optimum flach – kleine Abweichungen von Q* kosten wenig, deshalb rundet man in der Praxis gern auf Paletten." },
  { id: "bw2-180", cat: "bwl", topic: "Produktion", type: "quiz", emoji: "🧮", level: 2,
    q: "Jahresbedarf 10.000 Stück, Kosten je Bestellung 50 €, Lagerkosten 1 € pro Stück und Jahr. Optimale Bestellmenge?",
    options: ["500 Stück", "707 Stück", "1.000 Stück", "2.000 Stück"],
    answer: 2,
    explain: "√(2 × 10.000 × 50 / 1) = √1.000.000 = **1.000 Stück** → 10 Bestellungen pro Jahr." },
  { id: "bw2-181", cat: "bwl", topic: "Produktion", type: "quiz", emoji: "✖️", level: 3,
    q: "Die fixen Kosten pro Bestellung vervierfachen sich. Wie ändert sich die optimale Bestellmenge nach Andler?",
    options: ["Sie vervierfacht sich", "Sie bleibt gleich", "Sie halbiert sich", "Sie verdoppelt sich"],
    answer: 3,
    explain: "Q* hängt von der **Wurzel** ab: √4 = 2 → **doppelte Bestellmenge**. Genauso: Lagerkosten vervierfacht → Q* halbiert." },
  { id: "bw2-182", cat: "bwl", topic: "Produktion", type: "whatif", emoji: "🔧", level: 2,
    q: "Was passiert, wenn eine Fabrik ihre Rüstzeiten drastisch senkt (SMED)?",
    steps: ["Rüstkosten pro Los sinken", "Optimale Losgröße wird kleiner", "Weniger Bestände, kürzere Durchlaufzeit", "Mehr Flexibilität für Varianten"],
    text: "Das ist der Kern des Toyota-Ansatzes: Statt große Lose als gegeben hinzunehmen, senkt man die Rüstzeit (Single Minute Exchange of Die). Andler wird so vom Rechenrezept zum Hebel." },
  { id: "bw2-183", cat: "bwl", topic: "Produktion", type: "flashcard", emoji: "⏰", level: 1,
    term: "Just-in-Time (JIT)",
    def: "Material wird genau dann geliefert, wenn es gebraucht wird – in der benötigten Menge. Ziel: Lagerbestände und gebundenes Kapital minimieren.",
    example: "Voraussetzungen: zuverlässige Lieferanten, stabile Planung, gute Logistik. Nachteil: Jede Störung schlägt sofort auf die Produktion durch." },
  { id: "bw2-184", cat: "bwl", topic: "Produktion", type: "flashcard", emoji: "🚗", level: 3,
    term: "Just-in-Sequence (JIS)",
    def: "Steigerung von JIT: Teile kommen nicht nur pünktlich, sondern in der exakten **Reihenfolge** der Montage – passend zum jeweiligen Fahrzeug am Band.",
    example: "Der Sitzlieferant liefert für Auto 1 rote Ledersitze, für Auto 2 schwarze Stoffsitze – exakt in Bandreihenfolge, oft aus einem Werk direkt neben dem OEM." },
  { id: "bw2-185", cat: "bwl", topic: "Produktion", type: "fact", emoji: "🏯", level: 1,
    title: "Lean: Verschwendung (Muda) eliminieren",
    text: "Aus dem Toyota-Produktionssystem (Taiichi Ohno): Alles, was keinen Kundennutzen stiftet, ist Verschwendung. Sieben klassische Arten: Transport, Bestände, Bewegung, Warten, Überproduktion, Überbearbeitung, Fehler.",
    more: "Eselsbrücke **TIMWOOD**: Transport, Inventory, Motion, Waiting, Overproduction, Overprocessing, Defects. Überproduktion gilt als schlimmste Form, weil sie alle anderen verdeckt. Oft ergänzt: ungenutztes Mitarbeiterpotenzial." },
  { id: "bw2-186", cat: "bwl", topic: "Produktion", type: "flashcard", emoji: "🪜", level: 1,
    term: "Kaizen",
    def: "Japanisch für „Veränderung zum Besseren“: kontinuierliche Verbesserung in kleinen Schritten, getragen von allen Mitarbeitenden – statt seltener großer Innovationssprünge.",
    example: "Ein Werker schlägt vor, das Werkzeug 30 cm näher zu hängen: spart 2 Sekunden pro Takt – bei 500 Takten am Tag fast 17 Minuten." },
  { id: "bw2-187", cat: "bwl", topic: "Produktion", type: "quiz", emoji: "🗃️", level: 2,
    q: "Was beschreibt Kanban am besten?",
    options: ["Ein Pull-System: Verbrauch löst per Karte Nachschub aus", "Ein Push-System nach zentralem Produktionsplan", "Ein Qualitätsmanagement-Zertifikat", "Eine Methode zur Lieferantenbewertung"],
    answer: 0,
    explain: "Kanban (jap. „Karte“): Erst wenn ein Behälter leer ist, wird über die Karte Nachschub angefordert. Produziert wird, was **verbraucht** wurde – nicht, was geplant war." },
  { id: "bw2-188", cat: "bwl", topic: "Produktion", type: "order", emoji: "🎯", level: 3,
    q: "Ordne die Phasen des Six-Sigma-Zyklus DMAIC.",
    items: ["Define", "Measure", "Analyze", "Improve", "Control"],
    explain: "Problem definieren → Ist-Zustand messen → Ursachen analysieren → verbessern → Ergebnis absichern. Der Zyklus ist datengetrieben: Ohne Messung keine Verbesserung." },
  { id: "bw2-189", cat: "bwl", topic: "Produktion", type: "number", emoji: "🎯", level: 3,
    value: "3,4", label: "Fehler pro Million Möglichkeiten bei Six Sigma",
    text: "Six Sigma (bei Motorola in den 1980ern entwickelt) zielt auf eine Prozessqualität mit höchstens 3,4 Fehlern pro Million Fehlermöglichkeiten (DPMO).",
    more: "Die 3,4 enthalten eine Konvention: eine angenommene langfristige Prozessverschiebung um 1,5 Sigma. Ohne diese Verschiebung wären es bei ±6σ nur rund 0,002 Fehler pro Million. Zum Vergleich: 3 Sigma ≈ 66.800 DPMO." },
  { id: "bw2-190", cat: "bwl", topic: "Produktion", type: "truefalse", emoji: "✂️", level: 2,
    q: "Lean Management ist im Kern ein Programm zum Personalabbau.",
    answer: false,
    explain: "Lean zielt auf **Verschwendung in Prozessen**, nicht auf Köpfe. Wird Lean als Stellenabbau verkauft, stirbt die Mitarbeit an Kaizen – die Leute verbessern sich nicht selbst weg. Toyota setzte freie Kapazität oft für Wachstum ein." },
  { id: "bw2-191", cat: "bwl", topic: "Produktion", type: "whatif", emoji: "🍾", level: 3,
    q: "Was passiert, wenn die Engpassmaschine einer Linie eine Stunde stillsteht?",
    steps: ["Output der ganzen Linie sinkt", "Die Stunde ist für das System verloren", "Vor dem Engpass staut sich Material", "Verlust = DB pro Engpassstunde"],
    text: "Kern der **Theory of Constraints** (Goldratt): Eine Stunde am Engpass ist eine Stunde des Gesamtsystems; eine gesparte Stunde an einer Nicht-Engpass-Maschine ist dagegen wertlos. Deshalb: Engpass nie leerlaufen lassen, Puffer davor, Wartung außerhalb der Schicht." },

  // ── Logistik ──
  { id: "bw2-192", cat: "bwl", topic: "Logistik", type: "fact", emoji: "🔠", level: 1,
    title: "ABC-Analyse: Wenige Teile, großer Wert",
    text: "Sortiert Artikel nach Verbrauchswert. Typisch: **A-Teile** ≈ 20 % der Artikel, aber ≈ 80 % des Werts; C-Teile ≈ 50 % der Artikel, aber nur ≈ 5 % des Werts.",
    more: "Konsequenz: A-Teile eng steuern (genaue Disposition, Verhandlungen, JIT), C-Teile maximal vereinfachen (Kanban, Rahmenverträge, C-Teile-Management durch Dienstleister). Basis ist das Pareto-Prinzip." },
  { id: "bw2-193", cat: "bwl", topic: "Logistik", type: "quiz", emoji: "🔠", level: 1,
    q: "Was kennzeichnet A-Güter in der ABC-Analyse?",
    options: ["Viele Artikel mit geringem Wertanteil", "Konstanter, gut planbarer Verbrauch", "Wenige Artikel mit hohem Wertanteil", "Besonders sperrige Artikel"],
    answer: 2,
    explain: "A = **wenige Artikel, hoher Verbrauchswert**. Planbarkeit beschreibt dagegen die XYZ-Analyse." },
  { id: "bw2-194", cat: "bwl", topic: "Logistik", type: "quiz", emoji: "📉", level: 2,
    q: "In der XYZ-Analyse ist ein Z-Artikel …",
    options: ["ein Artikel mit sehr unregelmäßigem, schwer prognostizierbarem Verbrauch", "ein Artikel mit konstantem Verbrauch", "ein Artikel mit sehr niedrigem Wert", "ein Artikel mit trendförmigem, gut prognostizierbarem Verbrauch"],
    answer: 0,
    explain: "X = konstant, Y = schwankend/trendförmig, Z = **unregelmäßig**. Kombiniert mit ABC: AX-Teile eignen sich ideal für JIT, AZ-Teile eher für Einzelbeschaffung nach Bedarf." },
  { id: "bw2-195", cat: "bwl", topic: "Logistik", type: "flashcard", emoji: "🐂", level: 2,
    term: "Bullwhip-Effekt (Peitscheneffekt)",
    def: "Kleine Nachfrageschwankungen beim Endkunden schaukeln sich entlang der Lieferkette zu immer größeren Bestellschwankungen auf – vom Händler über den Großhandel bis zum Rohstofflieferanten.",
    example: "Klassisch untersucht bei Pampers-Windeln (Procter & Gamble): stabiler Verbrauch, aber stark schwankende Bestellungen. Gegenmittel: Nachfragedaten teilen (POS-Daten), kleinere Lose, VMI." },
  { id: "bw2-196", cat: "bwl", topic: "Logistik", type: "whatif", emoji: "🐂", level: 2,
    q: "Was passiert, wenn die Endkundennachfrage einmalig um 10 % steigt?",
    steps: ["Händler bestellt +10 % plus Sicherheitspuffer", "Großhändler sieht +20 %, bestellt mehr", "Hersteller erweitert Kapazität", "Nachfrage normalisiert sich → Überbestände"],
    text: "Jede Stufe sieht nur die Bestellungen der nächsten, nicht die echte Nachfrage – und legt Puffer drauf. So entstand nach der Corona-Knappheit 2021/22 vielerorts eine Lagerschwemme 2023." },
  { id: "bw2-197", cat: "bwl", topic: "Logistik", type: "quiz", emoji: "🧮", level: 2,
    q: "Wareneinsatz 1,2 Mio € pro Jahr, durchschnittlicher Lagerbestand 200.000 €. Durchschnittliche Lagerdauer (360 Tage)?",
    options: ["6 Tage", "30 Tage", "120 Tage", "60 Tage"],
    answer: 3,
    explain: "Umschlagshäufigkeit = 1,2 Mio / 200.000 = 6. Lagerdauer = 360 / 6 = **60 Tage**. Doppelte Umschlagshäufigkeit → halbe Kapitalbindung im Lager." },
  { id: "bw2-198", cat: "bwl", topic: "Logistik", type: "quiz", emoji: "🔔", level: 2,
    q: "Tagesverbrauch 50 Stück, Wiederbeschaffungszeit 6 Tage, Sicherheitsbestand 100 Stück. Meldebestand?",
    options: ["300 Stück", "400 Stück", "350 Stück", "156 Stück"],
    answer: 1,
    explain: "Meldebestand = Tagesverbrauch × Wiederbeschaffungszeit + Sicherheitsbestand = 50 × 6 + 100 = **400 Stück**. Fällt der Bestand darauf, wird bestellt." },
  { id: "bw2-199", cat: "bwl", topic: "Logistik", type: "flashcard", emoji: "🛟", level: 2,
    term: "Sicherheitsbestand",
    def: "Eiserne Reserve gegen Unsicherheit bei Nachfrage und Lieferzeit. Wächst mit der Schwankung der Nachfrage, der Wiederbeschaffungszeit und dem angestrebten Servicegrad.",
    example: "Zielkonflikt: Servicegrad von 95 % auf 99 % zu erhöhen, kostet überproportional viel Bestand." },
  { id: "bw2-200", cat: "bwl", topic: "Logistik", type: "whatif", emoji: "🚢", level: 3,
    q: "Was passiert, wenn bei Just-in-Time-Fertigung eine zentrale Transportroute blockiert ist?",
    steps: ["Teile kommen nicht an", "Kein Puffer im Lager", "Bänder stehen still, Umsatz fällt aus", "Firmen bauen Puffer und Zweitquellen auf"],
    text: "Die Blockade des Suezkanals durch die „Ever Given“ (2021) und die Chipkrise zeigten die Kehrseite schlanker Lieferketten. Seitdem gilt: **Just-in-Case** ergänzt Just-in-Time – Resilienz kostet Bestand." },
  { id: "bw2-201", cat: "bwl", topic: "Logistik", type: "truefalse", emoji: "🔗", level: 2,
    q: "Dual oder Multiple Sourcing senkt das Lieferrisiko, kann aber die Einkaufspreise erhöhen.",
    answer: true,
    explain: "Wer Volumen auf mehrere Lieferanten verteilt, verliert Mengenrabatte und Verhandlungsmacht und hat mehr Koordinationsaufwand. Dafür hängt die Produktion nicht an einem einzigen Werk (**Single-Source-Risiko**)." },
  { id: "bw2-202", cat: "bwl", topic: "Logistik", type: "order", emoji: "🔗", level: 2,
    q: "Ordne die Prozesse des SCOR-Modells entlang des Materialflusses.",
    items: ["Source (beschaffen)", "Make (herstellen)", "Deliver (liefern)", "Return (Rückführung)"],
    explain: "Das SCOR-Modell (Supply Chain Operations Reference) beschreibt Lieferketten mit Plan als übergreifendem Prozess sowie Source, Make, Deliver und Return. Es dient als gemeinsame Sprache für Benchmarking." },
  { id: "bw2-203", cat: "bwl", topic: "Logistik", type: "truefalse", emoji: "🏚️", level: 1,
    q: "Hohe Lagerbestände sind unproblematisch, weil sie ja Vermögen in der Bilanz sind.",
    answer: false,
    explain: "Lager bindet Kapital und verursacht Kosten für Zins, Fläche, Versicherung, Schwund und Veralterung – Praktiker rechnen grob mit **15–25 % des Lagerwerts pro Jahr**. Und Lean sagt: Bestände verstecken Probleme." },
);
